@Test
public void testIllegalNodeRegistration() throws ClientManagerException, IOException, InterruptedException, TException {
    ConfigNodeWrapper configNodeWrapper = EnvFactory.getEnv().generateRandomConfigNodeWrapper();
    DataNodeWrapper dataNodeWrapper = EnvFactory.getEnv().generateRandomDataNodeWrapper();
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        /* Register with error cluster name */
        TConfigNodeRegisterReq configNodeRegisterReq = ConfigNodeTestUtils.generateTConfigNodeRegisterReq(ERROR_CLUSTER_NAME, configNodeWrapper);
        configNodeRegisterReq.getClusterParameters().setConfigNodeConsensusProtocolClass(testConsensusProtocolClass);
        TConfigNodeRegisterResp configNodeRegisterResp = client.registerConfigNode(configNodeRegisterReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), configNodeRegisterResp.getStatus().getCode());
        Assert.assertTrue(configNodeRegisterResp.getStatus().getMessage().contains("cluster are inconsistent"));
        TDataNodeRegisterReq dataNodeRegisterReq = ConfigNodeTestUtils.generateTDataNodeRegisterReq(ERROR_CLUSTER_NAME, dataNodeWrapper);
        TDataNodeRegisterResp dataNodeRegisterResp = client.registerDataNode(dataNodeRegisterReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRegisterResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRegisterResp.getStatus().getMessage().contains("cluster are inconsistent"));
    }
}

@Test
public void testConflictNodeRegistration() throws ClientManagerException, InterruptedException, TException, IOException {
    /* Test ConfigNode conflict register */
    // Construct a ConfigNodeWrapper that conflicts in consensus port with an existed one.
    ConfigNodeWrapper conflictConfigNodeWrapper = EnvFactory.getEnv().generateRandomConfigNodeWrapper();
    conflictConfigNodeWrapper.setConsensusPort(EnvFactory.getEnv().getConfigNodeWrapper(1).getConsensusPort());
    conflictConfigNodeWrapper.changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getConfigNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getConfigNodeCommonConfig(), null);
    // The registration request should be rejected since there exists conflict port
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TConfigNodeRegisterReq req = ConfigNodeTestUtils.generateTConfigNodeRegisterReq(TEST_CLUSTER_NAME, conflictConfigNodeWrapper);
        req.getClusterParameters().setConfigNodeConsensusProtocolClass(testConsensusProtocolClass);
        TConfigNodeRegisterResp resp = client.registerConfigNode(req);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), resp.getStatus().getCode());
    }
    // The confignode-system.properties file should be empty before register
    File systemProperties = new File(conflictConfigNodeWrapper.getSystemPropertiesPath());
    Assert.assertFalse(systemProperties.exists());
    // The confignode-system.properties file should remain empty since the registration will fail
    EnvFactory.getEnv().registerNewConfigNode(conflictConfigNodeWrapper, false);
    Assert.assertFalse(systemProperties.exists());
    /* Construct a DataNodeWrapper that conflicts with an existed one. */
    // Construct a DataNodeWrapper that conflicts in internal port with an existed one.
    DataNodeWrapper conflictDataNodeWrapper = EnvFactory.getEnv().generateRandomDataNodeWrapper();
    conflictDataNodeWrapper.setInternalPort(EnvFactory.getEnv().getDataNodeWrapper(0).getInternalPort());
    conflictDataNodeWrapper.changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getDataNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getDataNodeCommonConfig(), null);
    // The registration request should be rejected since there exists conflict port
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TDataNodeRegisterReq req = ConfigNodeTestUtils.generateTDataNodeRegisterReq(TEST_CLUSTER_NAME, conflictDataNodeWrapper);
        TDataNodeRegisterResp resp = client.registerDataNode(req);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), resp.getStatus().getCode());
    }
    // The system.properties file should be empty before register
    systemProperties = new File(conflictDataNodeWrapper.getSystemPropertiesPath());
    Assert.assertFalse(systemProperties.exists());
    // The system.properties file should remain empty since the registration will fail
    EnvFactory.getEnv().registerNewDataNode(conflictDataNodeWrapper, false);
    Assert.assertFalse(systemProperties.exists());
}

@Test
public void testIllegalNodeRestart() throws ClientManagerException, IOException, InterruptedException, TException {
    ConfigNodeWrapper registeredConfigNodeWrapper = EnvFactory.getEnv().getConfigNodeWrapper(1);
    DataNodeWrapper registeredDataNodeWrapper = EnvFactory.getEnv().getDataNodeWrapper(0);
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        /* Restart with error cluster name */
        TDataNodeRestartReq dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(ERROR_CLUSTER_NAME, 2, registeredDataNodeWrapper);
        TDataNodeRestartResp dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("cluster are inconsistent"));
        /* Restart with error NodeId */
        dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(TEST_CLUSTER_NAME, 200, registeredDataNodeWrapper);
        dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("whose nodeId="));
        // Shutdown and check
        EnvFactory.getEnv().shutdownConfigNode(1);
        EnvFactory.getEnv().shutdownDataNode(0);
        EnvFactory.getEnv().ensureNodeStatus(Arrays.asList(EnvFactory.getEnv().getConfigNodeWrapper(1), EnvFactory.getEnv().getDataNodeWrapper(0)), Arrays.asList(NodeStatus.Unknown, NodeStatus.Unknown));
        /* Restart and updatePeer */
        // TODO: Delete this IT after enable modify internal TEndPoints
        int registeredConfigNodeId = -1;
        TShowClusterResp showClusterResp = client.showCluster();
        for (TConfigNodeLocation configNodeLocation : showClusterResp.getConfigNodeList()) {
            if (configNodeLocation.getConsensusEndPoint().getPort() == registeredConfigNodeWrapper.getConsensusPort()) {
                registeredConfigNodeId = configNodeLocation.getConfigNodeId();
                break;
            }
        }
        Assert.assertNotEquals(-1, registeredConfigNodeId);
        int originPort = registeredConfigNodeWrapper.getConsensusPort();
        registeredConfigNodeWrapper.setConsensusPort(-12345);
        registeredConfigNodeWrapper.setConsensusPort(originPort);
        int registeredDataNodeId = -1;
        showClusterResp = client.showCluster();
        for (TDataNodeLocation dataNodeLocation : showClusterResp.getDataNodeList()) {
            if (dataNodeLocation.getInternalEndPoint().getPort() == registeredDataNodeWrapper.getInternalPort()) {
                registeredDataNodeId = dataNodeLocation.getDataNodeId();
                break;
            }
        }
        Assert.assertNotEquals(-1, registeredDataNodeId);
        originPort = registeredDataNodeWrapper.getInternalPort();
        registeredDataNodeWrapper.setInternalPort(-12345);
        dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(TEST_CLUSTER_NAME, registeredDataNodeId, registeredDataNodeWrapper);
        dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("the internal TEndPoints"));
        registeredDataNodeWrapper.setInternalPort(originPort);
        // Restart and check
        EnvFactory.getEnv().startConfigNode(1);
        EnvFactory.getEnv().startDataNode(0);
        EnvFactory.getEnv().ensureNodeStatus(Arrays.asList(EnvFactory.getEnv().getConfigNodeWrapper(1), EnvFactory.getEnv().getDataNodeWrapper(0)), Arrays.asList(NodeStatus.Running, NodeStatus.Running));
    }
}

@Test
public void testIllegalNodeStartUp() throws IOException, ClientManagerException, InterruptedException, TException {
    ConfigNodeWrapper portConflictConfigNodeWrapper = EnvFactory.getEnv().generateRandomConfigNodeWrapper();
    DataNodeWrapper portConflictDataNodeWrapper = EnvFactory.getEnv().generateRandomDataNodeWrapper();
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TShowClusterResp showClusterResp = client.showCluster();
        int beforeStartConfigNodes = showClusterResp.getConfigNodeListSize();
        int beforeStartDataNodes = showClusterResp.getDataNodeListSize();
        // set ConfigNode port repeat
        portConflictConfigNodeWrapper.setConsensusPort(portConflictConfigNodeWrapper.getPort());
        portConflictConfigNodeWrapper.changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getConfigNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getConfigNodeCommonConfig(), null);
        portConflictConfigNodeWrapper.start();
        int afterStartConfigNodes;
        for (int i = 0; i < START_RETRY_NUM; ++i) {
            showClusterResp = client.showCluster();
            afterStartConfigNodes = showClusterResp.getConfigNodeListSize();
            Assert.assertEquals(beforeStartConfigNodes, afterStartConfigNodes);
            Thread.sleep(1000);
        }
        // set datanode port repeat
        portConflictDataNodeWrapper.setMppDataExchangePort(portConflictDataNodeWrapper.getDataRegionConsensusPort());
        portConflictDataNodeWrapper.changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getDataNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getDataNodeCommonConfig(), null);
        portConflictDataNodeWrapper.start();
        int afterStartDataNodes;
        for (int i = 0; i < START_RETRY_NUM; ++i) {
            showClusterResp = client.showCluster();
            afterStartDataNodes = showClusterResp.getDataNodeListSize();
            Assert.assertEquals(beforeStartDataNodes, afterStartDataNodes);
            Thread.sleep(1000);
        }
    }
}

@Test
public void showClusterAndNodesTest() throws Exception {
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        List<ConfigNodeWrapper> configNodeWrappers = EnvFactory.getEnv().getConfigNodeWrapperList();
        List<DataNodeWrapper> dataNodeWrappers = EnvFactory.getEnv().getDataNodeWrapperList();
        /* Test showCluster */
        TShowClusterResp showClusterResp = client.showCluster();
        // Check ConfigNodeLocation
        List<TConfigNodeLocation> configNodeLocations = showClusterResp.getConfigNodeList();
        for (TConfigNodeLocation configNodeLocation : configNodeLocations) {
            boolean found = false;
            for (ConfigNodeWrapper configNodeWrapper : configNodeWrappers) {
                if (configNodeWrapper.getIp().equals(configNodeLocation.getInternalEndPoint().getIp()) && configNodeWrapper.getPort() == configNodeLocation.getInternalEndPoint().getPort() && configNodeWrapper.getConsensusPort() == configNodeLocation.getConsensusEndPoint().getPort()) {
                    found = true;
                    break;
                }
            }
            assertTrue(found);
        }
        // Check DataNodeLocation
        List<TDataNodeLocation> dataNodeLocations = showClusterResp.getDataNodeList();
        for (TDataNodeLocation dataNodeLocation : dataNodeLocations) {
            boolean found = false;
            for (DataNodeWrapper dataNodeWrapper : dataNodeWrappers) {
                if (dataNodeWrapper.getIp().equals(dataNodeLocation.getInternalEndPoint().getIp()) && dataNodeWrapper.getPort() == dataNodeLocation.getClientRpcEndPoint().getPort() && dataNodeWrapper.getInternalPort() == dataNodeLocation.getInternalEndPoint().getPort() && dataNodeWrapper.getMppDataExchangePort() == dataNodeLocation.getMPPDataExchangeEndPoint().getPort() && dataNodeWrapper.getSchemaRegionConsensusPort() == dataNodeLocation.getSchemaRegionConsensusEndPoint().getPort() && dataNodeWrapper.getDataRegionConsensusPort() == dataNodeLocation.getDataRegionConsensusEndPoint().getPort()) {
                    found = true;
                    break;
                }
            }
            assertTrue(found);
        }
        /* Tests showClusterParameters */
        TShowVariablesResp showVariablesResp = client.showVariables();
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showVariablesResp.getStatus().getCode());
        TClusterParameters clusterParameters = showVariablesResp.getClusterParameters();
        TClusterParameters expectedParameters = ConfigNodeTestUtils.generateClusterParameters();
        Assert.assertEquals(testConsensusProtocolClass, clusterParameters.getConfigNodeConsensusProtocolClass());
        Assert.assertEquals(testConsensusProtocolClass, clusterParameters.getDataRegionConsensusProtocolClass());
        Assert.assertEquals(testConsensusProtocolClass, clusterParameters.getSchemaRegionConsensusProtocolClass());
        Assert.assertEquals(expectedParameters.getSeriesPartitionSlotNum(), clusterParameters.getSeriesPartitionSlotNum());
        Assert.assertEquals(expectedParameters.getSeriesPartitionExecutorClass(), clusterParameters.getSeriesPartitionExecutorClass());
        Assert.assertEquals(expectedParameters.getDefaultTTL(), clusterParameters.getDefaultTTL());
        Assert.assertEquals(expectedParameters.getTimePartitionInterval(), clusterParameters.getTimePartitionInterval());
        Assert.assertEquals(expectedParameters.getDataReplicationFactor(), clusterParameters.getDataReplicationFactor());
        Assert.assertEquals(expectedParameters.getSchemaReplicationFactor(), clusterParameters.getSchemaReplicationFactor());
        Assert.assertEquals(expectedParameters.getDataRegionPerDataNode(), clusterParameters.getDataRegionPerDataNode(), 0.01);
        Assert.assertEquals(expectedParameters.getSchemaRegionPerDataNode(), clusterParameters.getSchemaRegionPerDataNode(), 0.01);
        Assert.assertEquals(expectedParameters.getDiskSpaceWarningThreshold(), clusterParameters.getDiskSpaceWarningThreshold(), 0.01);
        Assert.assertEquals(expectedParameters.getReadConsistencyLevel(), clusterParameters.getReadConsistencyLevel());
        /* Test showConfigNodes */
        TShowConfigNodesResp showConfigNodesResp = client.showConfigNodes();
        // Check ConfigNodeInfo
        List<TConfigNodeInfo> configNodesInfo = showConfigNodesResp.getConfigNodesInfoList();
        for (TConfigNodeInfo configNodeInfo : configNodesInfo) {
            boolean found = false;
            for (ConfigNodeWrapper configNodeWrapper : configNodeWrappers) {
                if (configNodeWrapper.getIp().equals(configNodeInfo.getInternalAddress()) && configNodeWrapper.getPort() == configNodeInfo.getInternalPort()) {
                    found = true;
                    break;
                }
            }
            assertTrue(found);
        }
        /* Test showDataNodes */
        TShowDataNodesResp showDataNodesResp = client.showDataNodes();
        // Check DataNodeInfo
        List<TDataNodeInfo> dataNodesInfo = showDataNodesResp.getDataNodesInfoList();
        for (TDataNodeInfo dataNodeInfo : dataNodesInfo) {
            boolean found = false;
            for (DataNodeWrapper dataNodeWrapper : dataNodeWrappers) {
                if (dataNodeWrapper.getIp().equals(dataNodeInfo.getRpcAddresss()) && dataNodeWrapper.getPort() == dataNodeInfo.getRpcPort()) {
                    found = true;
                    break;
                }
            }
            assertTrue(found);
        }
    }
}

@Test
public void removeAndStopConfigNodeTest() throws Exception {
    TShowClusterResp showClusterResp;
    TSStatus status;
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // Test remove ConfigNode
        showClusterResp = client.showCluster();
        TConfigNodeLocation removedConfigNodeLocation = showClusterResp.getConfigNodeList().get(1);
        status = client.removeConfigNode(removedConfigNodeLocation);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // Waiting for RemoveConfigNodeProcedure
        boolean isRemoved = false;
        for (int retry = 0; retry < 10; retry++) {
            showClusterResp = client.showCluster();
            if (showClusterResp.getStatus().getCode() == TSStatusCode.SUCCESS_STATUS.getStatusCode() && showClusterResp.getConfigNodeListSize() == testConfigNodeNum - 1) {
                isRemoved = true;
                break;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        if (!isRemoved) {
            fail("Remove ConfigNode failed");
        }
        // Test stop ConfigNode
        status = client.stopConfigNode(removedConfigNodeLocation);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
    }
}

@Test
public void queryAndRemoveDataNodeTest() throws Exception {
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // Pick a registered DataNode
        TDataNodeLocation dataNodeLocation = new TDataNodeLocation();
        TShowDataNodesResp showDataNodesResp = client.showDataNodes();
        TDataNodeInfo dataNodeInfo = showDataNodesResp.getDataNodesInfoList().get(0);
        dataNodeLocation.setDataNodeId(dataNodeInfo.getDataNodeId());
        dataNodeLocation.setClientRpcEndPoint(new TEndPoint(dataNodeInfo.getRpcAddresss(), dataNodeInfo.getRpcPort()));
        dataNodeLocation.setMPPDataExchangeEndPoint(new TEndPoint(dataNodeInfo.getRpcAddresss(), dataNodeInfo.getRpcPort() + 1));
        dataNodeLocation.setInternalEndPoint(new TEndPoint(dataNodeInfo.getRpcAddresss(), dataNodeInfo.getRpcPort() + 2));
        dataNodeLocation.setDataRegionConsensusEndPoint(new TEndPoint(dataNodeInfo.getRpcAddresss(), dataNodeInfo.getRpcPort() + 3));
        dataNodeLocation.setSchemaRegionConsensusEndPoint(new TEndPoint(dataNodeInfo.getRpcAddresss(), dataNodeInfo.getRpcPort() + 4));
        /* Test query one DataNodeInfo */
        TDataNodeConfigurationResp dataNodeConfigurationResp = client.getDataNodeConfiguration(dataNodeLocation.getDataNodeId());
        Map<Integer, TDataNodeConfiguration> configurationMap = dataNodeConfigurationResp.getDataNodeConfigurationMap();
        TDataNodeLocation dnLocation = dataNodeConfigurationResp.getDataNodeConfigurationMap().get(dataNodeLocation.getDataNodeId()).getLocation();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataNodeConfigurationResp.getStatus().getCode());
        assertEquals(1, configurationMap.size());
        assertEquals(dataNodeLocation, dnLocation);
        /* Test query all DataNodeConfiguration */
        dataNodeConfigurationResp = client.getDataNodeConfiguration(-1);
        configurationMap = dataNodeConfigurationResp.getDataNodeConfigurationMap();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataNodeConfigurationResp.getStatus().getCode());
        assertEquals(testDataNodeNum, configurationMap.size());
        /* Test remove DataNode */
        // Remove DataNode
        dataNodeLocation = dataNodeConfigurationResp.getDataNodeConfigurationMap().get(showDataNodesResp.getDataNodesInfoList().get(testDataNodeNum - 1).getDataNodeId()).getLocation();
        TDataNodeRemoveReq dataNodeRemoveReq = new TDataNodeRemoveReq(Collections.singletonList(dataNodeLocation));
        TDataNodeRemoveResp dataNodeRemoveResp = client.removeDataNode(dataNodeRemoveReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataNodeRemoveResp.getStatus().getCode());
        // Waiting for RemoveDataNodeProcedure
        for (int retry = 0; retry < 10; retry++) {
            showDataNodesResp = client.showDataNodes();
            if (showDataNodesResp.getStatus().getCode() == TSStatusCode.SUCCESS_STATUS.getStatusCode() && showDataNodesResp.getDataNodesInfoListSize() == testDataNodeNum - 1) {
                return;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        fail("Remove DataNode failed");
    }
}

@Test
public void testNodeShutdownReporter() throws ClientManagerException, IOException, InterruptedException, TException {
    EnvFactory.getEnv().shutdownConfigNode(1);
    EnvFactory.getEnv().shutdownDataNode(0);
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // The unknown Nodes should be detected immediately with the help of shutdown hook
        boolean isDetected = false;
        for (int retry = 0; retry < 5; retry++) {
            TShowClusterResp showClusterResp = client.showCluster();
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showClusterResp.getStatus().getCode());
            AtomicInteger unknownNum = new AtomicInteger(0);
            showClusterResp.getNodeStatus().forEach((nodeId, nodeStatus) -> {
                if (NodeStatus.Unknown.getStatus().equals(nodeStatus)) {
                    unknownNum.getAndIncrement();
                }
            });
            if (unknownNum.get() == 2) {
                isDetected = true;
                break;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        Assert.assertTrue(isDetected);
    }
}

@Test
public void clusterRestartTest() throws InterruptedException {
    // Shutdown all cluster nodes
    for (int i = 0; i < testConfigNodeNum; i++) {
        EnvFactory.getEnv().shutdownConfigNode(i);
    }
    for (int i = 0; i < testDataNodeNum; i++) {
        EnvFactory.getEnv().shutdownDataNode(i);
    }
    // Sleep 1s before restart
    TimeUnit.SECONDS.sleep(1);
    // Restart all cluster nodes
    for (int i = 0; i < testConfigNodeNum; i++) {
        EnvFactory.getEnv().startConfigNode(i);
    }
    for (int i = 0; i < testDataNodeNum; i++) {
        EnvFactory.getEnv().startDataNode(i);
    }
    ((AbstractEnv) EnvFactory.getEnv()).testWorkingNoUnknown();
}

@Test
public void clusterRestartAfterUpdateDataNodeTest() throws InterruptedException, ClientManagerException, IOException, TException {
    // Shutdown all DataNodes
    for (int i = 0; i < testDataNodeNum; i++) {
        EnvFactory.getEnv().shutdownDataNode(i);
    }
    TimeUnit.SECONDS.sleep(1);
    List<DataNodeWrapper> dataNodeWrapperList = EnvFactory.getEnv().getDataNodeWrapperList();
    for (int i = 0; i < testDataNodeNum; i++) {
        // Modify DataNode clientRpcEndPoint
        int[] portList = EnvUtils.searchAvailablePorts();
        dataNodeWrapperList.get(i).setPort(portList[0]);
        // Update DataNode files' names
        dataNodeWrapperList.get(i).renameFile();
    }
    // Restart DataNodes
    for (int i = 0; i < testDataNodeNum; i++) {
        dataNodeWrapperList.get(i).changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getDataNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getDataNodeCommonConfig(), (MppJVMConfig) EnvFactory.getEnv().getConfig().getDataNodeJVMConfig());
        EnvFactory.getEnv().startDataNode(i);
    }
    // Check DataNode status
    EnvFactory.getEnv().ensureNodeStatus(Arrays.asList(EnvFactory.getEnv().getDataNodeWrapper(0), EnvFactory.getEnv().getDataNodeWrapper(1)), Arrays.asList(NodeStatus.Running, NodeStatus.Running));
    // Check DataNode EndPoint
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TShowClusterResp showClusterResp = client.showCluster();
        ConfigNodeTestUtils.checkNodeConfig(showClusterResp.getConfigNodeList(), showClusterResp.getDataNodeList(), EnvFactory.getEnv().getConfigNodeWrapperList(), dataNodeWrapperList);
    }
}

