        resp.getRegionInfoList().forEach(regionInfo -> {
            switch(regionInfo.getConsensusGroupId().getType()) {
                case SchemaRegion:
                    schemaRegionGroupNum.getAndIncrement();
                    break;
                case DataRegion:
                default:
                    dataRegionGroupNum.getAndIncrement();
                    break;
            }
        });
