    long totalTime = 0;
    int logsCount = testSeriesPartitionNum / testSeriesPartitionBatchSize * testTimePartitionNum / testTimePartitionBatchSize;
    for (int sid = 0; sid < testSeriesPartitionNum; sid += testSeriesPartitionBatchSize) {
        for (int tid = 0; tid < testTimePartitionNum; tid += testTimePartitionBatchSize) {
            long startTime = System.currentTimeMillis();
            // Prepare PartitionSlotsMap
            Map<String, Map<TSeriesPartitionSlot, TTimeSlotList>> partitionSlotsMap = ConfigNodeTestUtils.constructPartitionSlotsMap(sg, sid, sid + testSeriesPartitionBatchSize, tid, tid + testTimePartitionBatchSize, defaultTimePartitionInterval);
            // Create DataPartitions
            TDataPartitionReq dataPartitionReq = new TDataPartitionReq(partitionSlotsMap);
            TDataPartitionTableResp dataPartitionTableResp = null;
            for (int retry = 0; retry < 5; retry++) {
                try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
                    dataPartitionTableResp = client.getOrCreateDataPartitionTable(dataPartitionReq);
                    if (dataPartitionTableResp != null) {
                        break;
                    }
                } catch (Exception e) {
                    // Retry sometimes in order to avoid request timeout
                    LOGGER.error(e.getMessage());
                    TimeUnit.SECONDS.sleep(1);
                }
            }
            // Validate DataPartitions
            Assert.assertNotNull(dataPartitionTableResp);
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataPartitionTableResp.getStatus().getCode());
            Assert.assertNotNull(dataPartitionTableResp.getDataPartitionTable());
            ConfigNodeTestUtils.checkDataPartitionTable(sg, sid, sid + testSeriesPartitionBatchSize, tid, tid + testTimePartitionBatchSize, defaultTimePartitionInterval, dataPartitionTableResp.getDataPartitionTable());
            long endTime = System.currentTimeMillis();
            totalTime += endTime - startTime;
        }
    }
    String result = "IoTDBConfigNodeConsensusEfficiencyIT Finished." + "\n\t" + String.format("Test consensus protocol class: %s", testConsensusProtocolClass) + "\n\t" + String.format("The number of consensus logs: %d", logsCount) + "\n\t" + String.format("The number of DataPartitions per log: %d", testSeriesPartitionBatchSize * testTimePartitionBatchSize) + "\n\t" + String.format("The approximate size of each log: %dBytes", testSeriesPartitionBatchSize * testTimePartitionBatchSize * approximateDataPartitionSizeInBytes) + "\n\t" + String.format("Total time consuming: %.2fs", (double) totalTime / 1000) + "\n\t" + String.format("Average time for each log: %.2fms", (double) totalTime / logsCount);
    LOGGER.info(result);
}

