                }
            });
            if (!containUnknown.get()) {
                break;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        // Check Region count and status
        for (int i = 0; i < 10; i++) {
            runningCnt = 0;
            unknownCnt = 0;
            readOnlyCnt = 0;
            removingCnt = 0;
