        ConfigNodeTestUtils.checkDataPartitionTable(sg, 1, 1 + testSeriesPartitionBatchSize, 1, 1 + testTimePartitionBatchSize, testTimePartitionInterval, dataPartitionTableResp.getDataPartitionTable());
        /* Check Region distribution */
        showRegionResp = client.showRegion(new TShowRegionReq());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showRegionResp.getStatus().getCode());
        // There should be 2 RegionGroups
        Assert.assertEquals(6, showRegionResp.getRegionInfoListSize());
        // The new RegionGroup should keep away from the ReadOnly DataNode
        Map<Integer, AtomicInteger> regionCounter = new ConcurrentHashMap<>();
        showRegionResp.getRegionInfoList().forEach(regionInfo -> regionCounter.computeIfAbsent(regionInfo.getDataNodeId(), empty -> new AtomicInteger(0)).getAndIncrement());
        dataNodeIdSet.forEach(dataNodeId -> regionCounter.get(dataNodeId).getAndDecrement());
        TShowDataNodesResp showDataNodesResp = client.showDataNodes();
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showDataNodesResp.getStatus().getCode());
        regionCounter.forEach((dataNodeId, regionCount) -> {
            String nodeStatus = showDataNodesResp.getDataNodesInfoList().stream().filter(dataNodeInfo -> dataNodeInfo.getDataNodeId() == dataNodeId).findFirst().orElse(new TDataNodeInfo().setStatus("ERROR")).getStatus();
            if (NodeStatus.ReadOnly.getStatus().equals(nodeStatus)) {
                Assert.assertEquals(0, regionCount.get());
            } else if (NodeStatus.Running.getStatus().equals(nodeStatus)) {
                Assert.assertEquals(1, regionCount.get());
            } else {
                Assert.fail();
            }
        });
    }
}

@Test
public void testUnknownDataNode() throws Exception {
    // Shutdown a DataNode, the ConfigNode should still be able to create RegionGroup
    EnvFactory.getEnv().shutdownDataNode(testDataNodeId);
    EnvFactory.getEnv().ensureNodeStatus(Collections.singletonList(EnvFactory.getEnv().getDataNodeWrapper(testDataNodeId)), Collections.singletonList(NodeStatus.Unknown));
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // Wait for shutdown check
        TShowClusterResp showClusterResp;
        while (true) {
            AtomicBoolean containUnknown = new AtomicBoolean(false);
            TShowDataNodesResp showDataNodesResp = client.showDataNodes();
            showDataNodesResp.getDataNodesInfoList().forEach(dataNodeInfo -> {
                if (NodeStatus.Unknown.getStatus().equals(dataNodeInfo.getStatus())) {
                    containUnknown.set(true);
                }
            });
            if (containUnknown.get()) {
                break;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        int runningCnt = 0;
        int unknownCnt = 0;
        showClusterResp = client.showCluster();
        for (TDataNodeLocation dataNodeLocation : showClusterResp.getDataNodeList()) {
            if (NodeStatus.Running.getStatus().equals(showClusterResp.getNodeStatus().get(dataNodeLocation.getDataNodeId()))) {
                runningCnt += 1;
            } else if (NodeStatus.Unknown.getStatus().equals(showClusterResp.getNodeStatus().get(dataNodeLocation.getDataNodeId()))) {
                unknownCnt += 1;
            }
        }
        Assert.assertEquals(2, runningCnt);
        Assert.assertEquals(1, unknownCnt);
        // Test getOrCreateDataPartition, ConfigNode should create DataPartition and return
        Map<String, Map<TSeriesPartitionSlot, TTimeSlotList>> partitionSlotsMap = ConfigNodeTestUtils.constructPartitionSlotsMap(sg, 0, testSeriesPartitionBatchSize, 0, testTimePartitionBatchSize, testTimePartitionInterval);
        TDataPartitionReq dataPartitionReq = new TDataPartitionReq(partitionSlotsMap);
        TDataPartitionTableResp dataPartitionTableResp = null;
