            // Build new Client since it's unstable in Win8 environment
            try (SyncConfigNodeIServiceClient configNodeClient = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
                dataPartitionTableResp = configNodeClient.getOrCreateDataPartitionTable(dataPartitionReq);
                if (dataPartitionTableResp != null) {
                    break;
                }
            } catch (Exception e) {
                // Retry sometimes in order to avoid request timeout
                LOGGER.error(e.getMessage());
                TimeUnit.SECONDS.sleep(1);
            }
        }
        Assert.assertNotNull(dataPartitionTableResp);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataPartitionTableResp.getStatus().getCode());
        Assert.assertNotNull(dataPartitionTableResp.getDataPartitionTable());
        ConfigNodeTestUtils.checkDataPartitionTable(sg, 0, testSeriesPartitionBatchSize, 0, testTimePartitionBatchSize, testTimePartitionInterval, dataPartitionTableResp.getDataPartitionTable());
        // Check Region count
        runningCnt = 0;
        unknownCnt = 0;
        TShowRegionResp showRegionResp = client.showRegion(new TShowRegionReq());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showRegionResp.getStatus().getCode());
        for (TRegionInfo regionInfo : showRegionResp.getRegionInfoList()) {
            if (RegionStatus.Running.getStatus().equals(regionInfo.getStatus())) {
                runningCnt += 1;
            } else if (RegionStatus.Unknown.getStatus().equals(regionInfo.getStatus())) {
                unknownCnt += 1;
            }
        }
        // The runningCnt should be exactly twice as the unknownCnt
        // since there exists one DataNode is shutdown
        Assert.assertEquals(unknownCnt * 2, runningCnt);
        // Test getOrCreateDataPartition, ConfigNode should create DataPartition and return
        partitionSlotsMap = ConfigNodeTestUtils.constructPartitionSlotsMap(sg, 1, 1 + testSeriesPartitionBatchSize, 1, 1 + testTimePartitionBatchSize, testTimePartitionInterval);
        dataPartitionReq = new TDataPartitionReq(partitionSlotsMap);
        for (int retry = 0; retry < 5; retry++) {
            // Build new Client since it's unstable in Win8 environment
            try (SyncConfigNodeIServiceClient configNodeClient = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
                dataPartitionTableResp = configNodeClient.getOrCreateDataPartitionTable(dataPartitionReq);
                if (dataPartitionTableResp != null) {
                    break;
                }
            } catch (Exception e) {
                // Retry sometimes in order to avoid request timeout
                LOGGER.error(e.getMessage());
                TimeUnit.SECONDS.sleep(1);
            }
        }
        Assert.assertNotNull(dataPartitionTableResp);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataPartitionTableResp.getStatus().getCode());
        Assert.assertNotNull(dataPartitionTableResp.getDataPartitionTable());
        ConfigNodeTestUtils.checkDataPartitionTable(sg, 1, 1 + testSeriesPartitionBatchSize, 1, 1 + testTimePartitionBatchSize, testTimePartitionInterval, dataPartitionTableResp.getDataPartitionTable());
        // Check Region count and status
        runningCnt = 0;
        unknownCnt = 0;
        showRegionResp = client.showRegion(new TShowRegionReq());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showRegionResp.getStatus().getCode());
        for (TRegionInfo regionInfo : showRegionResp.getRegionInfoList()) {
            if (RegionStatus.Running.getStatus().equals(regionInfo.getStatus())) {
                runningCnt += 1;
            } else if (RegionStatus.Unknown.getStatus().equals(regionInfo.getStatus())) {
                unknownCnt += 1;
            }
        }
        // The runningCnt should be exactly twice as the unknownCnt
        // since there exists one DataNode is shutdown
        Assert.assertEquals(unknownCnt * 2, runningCnt);
        EnvFactory.getEnv().startDataNode(testDataNodeId);
        EnvFactory.getEnv().ensureNodeStatus(Collections.singletonList(EnvFactory.getEnv().getDataNodeWrapper(testDataNodeId)), Collections.singletonList(NodeStatus.Running));
        // All Regions should alive after the testDataNode is restarted
        boolean allRunning = true;
        for (int retry = 0; retry < 30; retry++) {
            allRunning = true;
            showRegionResp = client.showRegion(new TShowRegionReq());
            for (TRegionInfo regionInfo : showRegionResp.getRegionInfoList()) {
                if (!RegionStatus.Running.getStatus().equals(regionInfo.getStatus())) {
                    allRunning = false;
                    break;
                }
            }
            if (allRunning) {
                break;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        Assert.assertTrue(allRunning);
    }
