    expectedHeader = new String[] { "time_duration(root.*.d1.s1)", "time_duration(root.*.d2.s1)" };
    retArray = new String[] { "8,8," };
    resultSetEqualTest("select time_duration(s1) from root.** where time < 10 group by level=2", expectedHeader, retArray);
