@Test
public void orderByCanNotPushLimitTest() {
    // 1. value filter, can not push down LIMIT
    String[] expectedHeader = new String[] { "Time,Device,s1" };
    String[] retArray = new String[] { "3,root.db.d1,111," };
    resultSetEqualTest("SELECT * FROM root.db.** WHERE s1>40 ORDER BY TIME LIMIT 1 ALIGN BY DEVICE;", expectedHeader, retArray);
    // 2. order by expression, can not push down LIMIT
    retArray = new String[] { "3,root.db.d3,333," };
    resultSetEqualTest("SELECT * FROM root.db.** ORDER BY s1 DESC LIMIT 1 ALIGN BY DEVICE;", expectedHeader, retArray);
    // 3. time filter, can push down LIMIT
    retArray = new String[] { "2,root.db.d3,33,", "2,root.db.d2,22," };
    resultSetEqualTest("SELECT * FROM root.db.** WHERE time>1 and time<3 ORDER BY device DESC LIMIT 2 ALIGN BY DEVICE;", expectedHeader, retArray);
    // 4. both exist OFFSET and LIMIT, can push down LIMIT as OFFSET+LIMIT
    retArray = new String[] { "3,root.db.d2,222," };
    resultSetEqualTest("SELECT * FROM root.db.** ORDER BY time DESC OFFSET 1 LIMIT 1 ALIGN BY DEVICE;", expectedHeader, retArray);
}

