@Test
public void testInsertAlignedWithEmptyPage() throws SQLException {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("CREATE ALIGNED TIMESERIES root.lz.dev.GPS(S1 INT32 encoding=PLAIN compressor=SNAPPY, S2 INT32 encoding=PLAIN compressor=SNAPPY, S3 INT32 encoding=PLAIN compressor=SNAPPY) ");
        for (int i = 0; i < 100; i++) {
            if (i == 99) {
                statement.addBatch("insert into root.lz.dev.GPS(time,S1,S3) aligned values(" + i + "," + i + "," + i + ")");
            } else {
                statement.addBatch("insert into root.lz.dev.GPS(time,S1,S2) aligned values(" + i + "," + i + "," + i + ")");
            }
        }
        statement.executeBatch();
        statement.execute("flush");
        int rowCount = 0;
        try (ResultSet resultSet = statement.executeQuery("select S3 from root.lz.dev.GPS")) {
            while (resultSet.next()) {
                assertEquals(99, resultSet.getInt(2));
                rowCount++;
            }
            assertEquals(1, rowCount);
        }
        try (ResultSet resultSet = statement.executeQuery("select S2 from root.lz.dev.GPS")) {
            rowCount = 0;
            while (resultSet.next()) {
                assertEquals(rowCount, resultSet.getInt(2));
                rowCount++;
            }
            assertEquals(99, rowCount);
        }
        try (ResultSet resultSet = statement.executeQuery("select S1 from root.lz.dev.GPS")) {
            rowCount = 0;
            while (resultSet.next()) {
                assertEquals(rowCount, resultSet.getInt(2));
                rowCount++;
            }
            assertEquals(100, rowCount);
        }
    }
}

