@Test
public void testGrantAndGrantOpt() throws SQLException {
    // 1. CREATE USER1, USER2, USER3, testRole
    Connection adminCon = EnvFactory.getEnv().getConnection();
    Statement adminStmt = adminCon.createStatement();
    adminStmt.execute("CREATE USER user1 'password'");
    adminStmt.execute("CREATE USER user2 'password'");
    adminStmt.execute("CREATE USER user3 'password'");
    adminStmt.execute("CREATE ROLE testRole");
    adminStmt.execute("GRANT manage_database ON root.** TO ROLE testRole WITH GRANT OPTION");
    adminStmt.execute("GRANT READ_DATA ON root.t1.** TO ROLE testRole");
    adminStmt.execute("GRANT READ_SCHEMA ON root.t3.t2.** TO ROLE testRole WITH GRANT OPTION");
    // 2. USER1 has all privileges on root.**
    for (PrivilegeType item : PrivilegeType.values()) {
        String sql = "GRANT %s on root.** to USER user1";
        adminStmt.execute(String.format(sql, item.toString()));
    }
    // 3.admin lists privileges of user1
    ResultSet resultSet = adminStmt.executeQuery("LIST PRIVILEGES OF USER user1");
    String ans = ",,MANAGE_USER,false,\n" + ",,MANAGE_ROLE,false,\n" + ",,USE_TRIGGER,false,\n" + ",,USE_UDF,false,\n" + ",,USE_CQ,false,\n" + ",,USE_PIPE,false,\n" + ",,EXTEND_TEMPLATE,false,\n" + ",,MANAGE_DATABASE,false,\n" + ",,MAINTAIN,false,\n" + ",,AUDIT,false,\n" + ",root.**,READ_DATA,false,\n" + ",root.**,WRITE_DATA,false,\n" + ",root.**,READ_SCHEMA,false,\n" + ",root.**,WRITE_SCHEMA,false,\n";
    validateResultSet(resultSet, ans);
    // 4. USER2 has all privilegs on root.** with grant option;
    for (PrivilegeType item : PrivilegeType.values()) {
        String sql = "GRANT %s on root.** to USER user2 with grant option";
        adminStmt.execute(String.format(sql, item.toString()));
    }
    resultSet = adminStmt.executeQuery("LIST PRIVILEGES OF USER user2");
    ans = ",,MANAGE_USER,true,\n" + ",,MANAGE_ROLE,true,\n" + ",,USE_TRIGGER,true,\n" + ",,USE_UDF,true,\n" + ",,USE_CQ,true,\n" + ",,USE_PIPE,true,\n" + ",,EXTEND_TEMPLATE,true,\n" + ",,MANAGE_DATABASE,true,\n" + ",,MAINTAIN,true,\n" + ",,AUDIT,true,\n" + ",root.**,READ_DATA,true,\n" + ",root.**,WRITE_DATA,true,\n" + ",root.**,READ_SCHEMA,true,\n" + ",root.**,WRITE_SCHEMA,true,\n";
    validateResultSet(resultSet, ans);
    // now user1 has all privileges, user2 has all privileges with grant option, user3 doesn't have
    // privileges
    // 5. Login user1 to list user2 privileges will success
    // user1 cannot grant any privilegs to user3
    try (Connection userCon = EnvFactory.getEnv().getConnection("user1", "password");
        Statement userStmt = userCon.createStatement()) {
        try {
            resultSet = userStmt.executeQuery("LIST PRIVILEGES OF USER user1");
            ans = ",,MANAGE_USER,false,\n" + ",,MANAGE_ROLE,false,\n" + ",,USE_TRIGGER,false,\n" + ",,USE_UDF,false,\n" + ",,USE_CQ,false,\n" + ",,USE_PIPE,false,\n" + ",,EXTEND_TEMPLATE,false,\n" + ",,MANAGE_DATABASE,false,\n" + ",,MAINTAIN,false,\n" + ",,AUDIT,false,\n" + ",root.**,READ_DATA,false,\n" + ",root.**,WRITE_DATA,false,\n" + ",root.**,READ_SCHEMA,false,\n" + ",root.**,WRITE_SCHEMA,false,\n";
            validateResultSet(resultSet, ans);
            Assert.assertThrows(SQLException.class, () -> userStmt.execute("GRANT MANAGE_ROLE ON root.** TO USER user3"));
            Assert.assertThrows(SQLException.class, () -> userStmt.execute("REVOKE MANAGE_ROLE ON root.** FROM USER user2"));
        } finally {
            userStmt.close();
        }
    }
    // 6.Login user2 grant and revoke will success.
    try (Connection userCon = EnvFactory.getEnv().getConnection("user2", "password");
        Statement userStmt = userCon.createStatement()) {
        try {
            resultSet = userStmt.executeQuery("LIST PRIVILEGES OF USER user1");
            validateResultSet(resultSet, ans);
            userStmt.execute("GRANT MANAGE_ROLE ON root.** TO USER user3");
            resultSet = userStmt.executeQuery("LIST PRIVILEGES OF USER user3");
            ans = ",,MANAGE_ROLE,false,\n";
            validateResultSet(resultSet, ans);
            userStmt.execute("REVOKE MANAGE_ROLE ON root.** FROM USER user1");
            resultSet = userStmt.executeQuery("LIST PRIVILEGES OF USER user1");
            ans = ",,MANAGE_USER,false,\n" + ",,USE_TRIGGER,false,\n" + ",,USE_UDF,false,\n" + ",,USE_CQ,false,\n" + ",,USE_PIPE,false,\n" + ",,EXTEND_TEMPLATE,false,\n" + ",,MANAGE_DATABASE,false,\n" + ",,MAINTAIN,false,\n" + ",,AUDIT,false,\n" + ",root.**,READ_DATA,false,\n" + ",root.**,WRITE_DATA,false,\n" + ",root.**,READ_SCHEMA,false,\n" + ",root.**,WRITE_SCHEMA,false,\n";
            validateResultSet(resultSet, ans);
        } finally {
            userStmt.close();
        }
    }
    adminStmt.execute("GRANT ROLE testRole TO user3");
    // now user has:
    // 1. MANAGE_ROLE
    // 2. MANAGE_DATABASE with grant option
    // 3. READ_DATA on root.t1.**
    // 4. READ_SCHEMA on root.t3.t2.**
    try (Connection userCon = EnvFactory.getEnv().getConnection("user3", "password");
        Statement userStmt = userCon.createStatement()) {
        try {
            // because role's privilege
            userStmt.execute("GRANT manage_database ON root.** TO USER user1");
            Assert.assertThrows(SQLException.class, () -> userStmt.execute("GRANT READ_DATA ON root.t1.** TO USER user1"));
            userStmt.execute("GRANT READ_SCHEMA ON root.t3.t2.t3 TO USER user1");
            Assert.assertThrows(SQLException.class, () -> userStmt.execute("GRANT READ_DATA ON root.t1.t2.t3 TO USER user1"));
        } finally {
            userStmt.close();
        }
    }
    adminStmt.close();
}

@Test
public void testRevokeAndGrantOpt() throws SQLException {
    // 1. revoke from user/role
    Connection adminCon = EnvFactory.getEnv().getConnection();
    Statement adminStmt = adminCon.createStatement();
    adminStmt.execute("CREATE USER user1 'password'");
    adminStmt.execute("CREATE USER user2 'password'");
    // 2. user1 has all privileges with grant option on root.**
    //    user2 has all privileges without grant option on root.**
    //    user2 has all privileges without grant option on root.t1.**
    for (PrivilegeType item : PrivilegeType.values()) {
        String sql = "GRANT %s on root.** to USER user1 WITH GRANT OPTION";
        adminStmt.execute(String.format(sql, item));
        if (item.isPathRelevant()) {
            adminStmt.execute(String.format("GRANT %s on root.t1.** TO USER user2", item));
        }
        sql = "GRANT %s on root.** to USER user2";
        adminStmt.execute(String.format(sql, item));
    }
    Connection user1Con = EnvFactory.getEnv().getConnection();
    Statement user1Stmt = user1Con.createStatement();
    ResultSet resultSet;
    String ans = "";
    try {
        // revoke privileges on root.** and root.t1.**
        for (PrivilegeType item : PrivilegeType.values()) {
            user1Stmt.execute(String.format("REVOKE %s ON root.** FROM USER user2", item));
        }
        resultSet = user1Stmt.executeQuery("LIST PRIVILEGES OF USER user2");
        validateResultSet(resultSet, ans);
    } finally {
        user1Stmt.close();
        user1Con.close();
    }
    adminStmt.execute("REVOKE ALL ON root.** from USER user1");
    resultSet = adminStmt.executeQuery("LIST PRIVILEGES OF USER user1");
    validateResultSet(resultSet, ans);
    adminStmt.execute("GRANT READ,WRITE on root.t1.** TO USER user1");
    adminStmt.execute("REVOKE WRITE on root.** FROM USER user1");
    resultSet = adminStmt.executeQuery("LIST PRIVILEGES OF USER user1");
    ans = ",root.t1.**,READ_DATA,false,\n" + ",root.t1.**,READ_SCHEMA,false,\n";
    validateResultSet(resultSet, ans);
}

@Test
public void permissionTest() throws IllegalPathException {
    TSStatus status;
    List<String> userList = new ArrayList<>();
    userList.add("root");
    userList.add("tempuser0");
    userList.add("tempuser1");
    List<String> roleList = new ArrayList<>();
    roleList.add("temprole0");
    roleList.add("temprole1");
    TAuthorizerReq authorizerReq;
    TAuthorizerResp authorizerResp;
    TCheckUserPrivilegesReq checkUserPrivilegesReq;
    Set<Integer> pathPrivilegeList = new HashSet<>();
    pathPrivilegeList.add(PrivilegeType.READ_DATA.ordinal());
    Set<Integer> revokePathPrivilege = new HashSet<>();
    revokePathPrivilege.add(PrivilegeType.READ_DATA.ordinal());
    List<String> privilege = new ArrayList<>();
    privilege.add("root.** : READ_DATA");
    List<PartialPath> paths = new ArrayList<>();
    paths.add(new PartialPath("root.ln.**"));
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        cleanUserAndRole(client);
        // create user
        authorizerReq = new TAuthorizerReq(AuthorType.CREATE_USER.ordinal(), "tempuser0", "", "passwd", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        authorizerReq.setUserName("tempuser1");
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0, tempuser1
        // check user privileges
        checkUserPrivilegesReq = new TCheckUserPrivilegesReq("tempuser0", AuthUtils.serializePartialPathList(paths), PrivilegeType.MANAGE_USER.ordinal());
        status = client.checkUserPrivileges(checkUserPrivilegesReq).getStatus();
        assertEquals(TSStatusCode.NO_PERMISSION.getStatusCode(), status.getCode());
        // drop user
        authorizerReq = new TAuthorizerReq(AuthorType.DROP_USER.ordinal(), "tempuser1", "", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0
        // list user
        authorizerReq = new TAuthorizerReq(AuthorType.LIST_USER.ordinal(), "", "", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        authorizerResp = client.queryPermission(authorizerReq);
        status = authorizerResp.getStatus();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        userList.remove("tempuser1");
        assertEquals(userList, authorizerResp.getMemberInfo());
        // create role
        authorizerReq = new TAuthorizerReq(AuthorType.CREATE_ROLE.ordinal(), "", "temprole0", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        authorizerReq.setRoleName("temprole1");
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0,temprole0,temprole1
        // drop role
        authorizerReq = new TAuthorizerReq(AuthorType.DROP_ROLE.ordinal(), "", "temprole1", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0,temprole0
        // list role
        authorizerReq = new TAuthorizerReq(AuthorType.LIST_ROLE.ordinal(), "", "", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        authorizerResp = client.queryPermission(authorizerReq);
        status = authorizerResp.getStatus();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        roleList.remove("temprole1");
        assertEquals(roleList, authorizerResp.getMemberInfo());
        // alter user
        authorizerReq = new TAuthorizerReq(AuthorType.UPDATE_USER.ordinal(), "tempuser0", "", "", "newpwd", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // grant user
        List<PartialPath> nodeNameList = new ArrayList<>();
        nodeNameList.add(new PartialPath("root.ln.**"));
        authorizerReq = new TAuthorizerReq(AuthorType.GRANT_USER.ordinal(), "tempuser0", "", "", "", pathPrivilegeList, false, AuthUtils.serializePartialPathList(nodeNameList));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0: root.ln.** ,read_data
        //                temprole0
        // check user privileges
        checkUserPrivilegesReq = new TCheckUserPrivilegesReq("tempuser0", AuthUtils.serializePartialPathList(paths), PrivilegeType.READ_DATA.ordinal());
        status = client.checkUserPrivileges(checkUserPrivilegesReq).getStatus();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // grant role
        authorizerReq = new TAuthorizerReq(AuthorType.GRANT_ROLE.ordinal(), "", "temprole0", "", "", pathPrivilegeList, false, AuthUtils.serializePartialPathList(nodeNameList));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0: root.ln.** ,read_data
        //                temprole0: root.ln.** , read_data
        // grant role to user
        authorizerReq = new TAuthorizerReq(AuthorType.GRANT_USER_ROLE.ordinal(), "tempuser0", "temprole0", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(nodeNameList));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0: root.ln.** ,read_data; [temprole0]
        //                temprole0: root.ln.** , read_data
