            assertEquals(count, Double.parseDouble(resultSet.getString(2)), 0);
            assertEquals(count, Double.parseDouble(resultSet.getString(3)), 0);
            assertEquals(2 * Math.sin(1.0), Double.parseDouble(resultSet.getString(4)), 1e-5);
