        for (long row = 0; row < 100; row++) {
            int rowIndex = tablet.rowSize++;
            tablet.addTimestamp(rowIndex, timestamp);
            for (int s = 0; s < 3; s++) {
                long value = timestamp;
                tablet.addValue(schemaList.get(s).getMeasurementId(), rowIndex, value);
