    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        // udf class name should be STRING_LITERAL
        statement.execute("create function udf as 'org.apache.iotdb.db.query.udf.example.Adder'");
        // executed correctly
        try (ResultSet resultSet = statement.executeQuery("show functions")) {
            assertEquals(3, resultSet.getMetaData().getColumnCount());
            int count = 0;
            while (resultSet.next()) {
                StringBuilder stringBuilder = new StringBuilder();
                for (int i = 1; i <= resultSet.getMetaData().getColumnCount(); ++i) {
                    stringBuilder.append(resultSet.getString(i)).append(",");
                }
                String result = stringBuilder.toString();
                if (result.contains(TestConstant.FUNCTION_TYPE_NATIVE)) {
                    continue;
                }
                ++count;
            }
            Assert.assertEquals(1 + BuiltinTimeSeriesGeneratingFunctionEnum.values().length + BuiltinScalarFunctionEnum.values().length, count);
