@Test
public void timezoneTest() throws SQLException {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        String insertSQLTemplate = "insert into root.timezone(timestamp,tz1) values(%s,%s)";
        connection.setClientInfo("time_zone", "+08:00");
        // 1514779200000 = 2018-1-1T12:00:00+08:00
        statement.execute(String.format(insertSQLTemplate, "1514779200000", "1"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:01", "2"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:02+08:00", "3"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:03+09:00", "4"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:04+07:00", "5"));
        connection.setClientInfo("time_zone", "+09:00");
        statement.execute(String.format(insertSQLTemplate, "1514789200000", "6"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T14:00:05", "7"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:03+08:00", "8"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:06+07:00", "9"));
        // Asia/Almaty +06:00
        connection.setClientInfo("time_zone", "Asia/Almaty");
        statement.execute(String.format(insertSQLTemplate, "1514782807000", "10"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T11:00:08", "11"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T13:00:09+08:00", "12"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:10+07:00", "13"));
        ResultSet resultSet = statement.executeQuery("select * from root.**");
        int cnt = 0;
        try {
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(tz1);
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
        } finally {
            resultSet.close();
        }
        Assert.assertEquals(13, cnt);
    }
}

@Test
public void testTTL() throws SQLException, InterruptedException {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        try {
            statement.execute("SET TTL TO root.TTL_SG1 1000");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.DATABASE_NOT_EXIST.getStatusCode(), e.getErrorCode());
        }
        try {
            statement.execute("UNSET TTL TO root.TTL_SG1");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.DATABASE_NOT_EXIST.getStatusCode(), e.getErrorCode());
        }
        statement.execute("CREATE DATABASE root.TTL_SG1");
        statement.execute("CREATE TIMESERIES root.TTL_SG1.s1 WITH DATATYPE=INT64,ENCODING=PLAIN");
        try {
            statement.execute("SET TTL TO root.TTL_SG1.s1 1000");
        } catch (SQLException e) {
            e.printStackTrace();
            fail(e.getMessage());
        }
        statement.execute("CREATE DATABASE root.TTL_SG2");
        statement.execute("CREATE TIMESERIES root.TTL_SG2.s1 WITH DATATYPE=INT64,ENCODING=PLAIN");
        try {
            statement.execute("SET TTL TO root.TTL_SG2.s1 1000");
        } catch (SQLException e) {
            e.printStackTrace();
            fail(e.getMessage());
        }
        try {
            statement.execute("SET TTL TO root.** 1000");
        } catch (SQLException e) {
            e.printStackTrace();
            fail(e.getMessage());
        }
        try {
            statement.execute("UNSET TTL TO root.**");
        } catch (SQLException e) {
            e.printStackTrace();
            fail(e.getMessage());
        }
        long now = System.currentTimeMillis();
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 100 + i, i));
        }
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 100000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        statement.execute("SET TTL TO root.TTL_SG1 10000");
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(100, cnt);
        }
        for (int i = 0; i < 100; i++) {
            boolean caught = false;
            try {
                statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 500000 + i, i));
            } catch (SQLException e) {
                assertEquals(TSStatusCode.OUT_OF_TTL.getStatusCode(), e.getErrorCode());
            }
        }
        Thread.sleep(1000);
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(100, cnt);
        }
        statement.execute("UNSET TTL TO root.TTL_SG1");
        // make sure other nodes have applied UNSET TTL
        Thread.sleep(1000);
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 30000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertTrue(cnt >= 200);
        }
        statement.execute("CREATE DATABASE root.sg.TTL_SG3");
        statement.execute("CREATE DATABASE root.sg.TTL_SG4");
        // SG3
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.sg.TTL_SG3(timestamp, s1) VALUES (%d, %d)", now - 100 + i, i));
        }
        for (int i = 100; i < 200; i++) {
            statement.execute(String.format("INSERT INTO root.sg.TTL_SG3(timestamp, s1) VALUES (%d, %d)", now - 10000000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.sg.TTL_SG3")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        // SG4
        for (int i = 200; i < 300; i++) {
            statement.execute(String.format("INSERT INTO root.sg.TTL_SG4(timestamp, s1) VALUES (%d, %d)", now - 100 + i, i));
        }
        for (int i = 300; i < 400; i++) {
            statement.execute(String.format("INSERT INTO root.sg.TTL_SG4(timestamp, s1) VALUES (%d, %d)", now - 10000000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.sg.TTL_SG4")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        statement.execute("SET TTL TO root.sg.** 100000");
        try (ResultSet resultSet = statement.executeQuery("SELECT * FROM root.sg.**")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        for (int i = 0; i < 100; i++) {
            boolean caught = false;
            try {
                statement.execute(String.format("INSERT INTO root.sg.TTL_SG3(timestamp, s1) VALUES (%d, %d)", now - 5000000 + i, i));
            } catch (SQLException e) {
                assertEquals(TSStatusCode.OUT_OF_TTL.getStatusCode(), e.getErrorCode());
            }
        }
        for (int i = 100; i < 200; i++) {
            boolean caught = false;
            try {
                statement.execute(String.format("INSERT INTO root.sg.TTL_SG4(timestamp, s1) VALUES (%d, %d)", now - 5000000 + i, i));
            } catch (SQLException e) {
                assertEquals(TSStatusCode.OUT_OF_TTL.getStatusCode(), e.getErrorCode());
            }
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.sg.**")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        statement.execute("UNSET TTL TO root.sg.**");
        // make sure other nodes have applied UNSET TTL
        Thread.sleep(1000);
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.sg.TTL_SG3(timestamp, s1) VALUES (%d, %d)", now - 30000 + i, i));
        }
        for (int i = 100; i < 200; i++) {
            statement.execute(String.format("INSERT INTO root.sg.TTL_SG4(timestamp, s1) VALUES (%d, %d)", now - 30000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.sg.**")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertTrue(cnt >= 400);
        }
    }
}

