    String[] retArray = new String[] { "1,root.sg.d1.s1,1.0,FLOAT", "1,root.sg.d1.s2,1.0,FLOAT", "2,root.sg.d2.s1,1.0,FLOAT", "2,root.sg.d2.s2,1.0,FLOAT" };
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        try (ResultSet resultSet = statement.executeQuery("select last * from root.sg.* order by timeseries asc")) {
            int cnt = 0;
            while (resultSet.next()) {
                String ans = resultSet.getString(ColumnHeaderConstant.TIME) + "," + resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.VALUE) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE);
                assertEquals(retArray[cnt++], ans);
            }
            assertEquals(retArray.length, cnt);
        }
        statement.execute("set ttl to root.sg 1");
        try (ResultSet resultSet = statement.executeQuery("select last * from root.sg.* order by timeseries asc")) {
            assertFalse(resultSet.next());
        }
    } catch (SQLException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

