@Test
public void testKind1OutputTypeRestrict() {
    // BOOLEAN and other types cannot exist at the same time
    String[] expectedHeader = new String[] { TIMESTAMP_STR, "CASE WHEN root.sg.d1.s1 <= 0 THEN true WHEN root.sg.d1.s1 = 11 THEN false ELSE true END" };
    String[] retArray = new String[] { "0,true,", "1000000,false,", "20000000,true,", "210000000,true," };
    // success
    resultSetEqualTest("select case when s1<=0 then true when s1=11 then false else true end from root.sg.d1", expectedHeader, retArray);
    // fail
    assertTestFail("select case when s1<=0 then true else 22 end from root.sg.d1", "701: CASE expression: BOOLEAN and other types cannot exist at the same time");
    // TEXT and other types cannot exist at the same time
    expectedHeader = new String[] { TIMESTAMP_STR, "CASE WHEN root.sg.d1.s1 <= 0 THEN \"good\" WHEN root.sg.d1.s1 = 11 THEN \"bad\" ELSE \"okok\" END" };
    retArray = new String[] { "0,good,", "1000000,bad,", "20000000,okok,", "210000000,okok," };
    // success
    resultSetEqualTest("select case when s1<=0 then \"good\" when s1=11 then \"bad\" else \"okok\" end from root.sg.d1", expectedHeader, retArray);
    // fail
    assertTestFail("select case when s1<=0 then \"good\" else 22 end from root.sg.d1", "701: CASE expression: TEXT and other types cannot exist at the same time");
    // 4 numerical types(INT LONG FLOAT DOUBLE) can exist at the same time
    expectedHeader = new String[] { TIMESTAMP_STR, "result" };
    retArray = new String[] { "0,99.0,", "1000000,99.9000015258789,", "20000000,8.589934588E9,", "210000000,1000.0," };
    resultSetEqualTest("select case when s1=0 then 99 when s1=11 then 99.9 when s1=22 then 8589934588 when s1=33 then 999.9999999999 else 10086 end as `result` from root.sg.d1", expectedHeader, retArray);
}

