    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        ResultSet resultSet = statement.executeQuery("select * from root.** where time>10");
        ResultSetMetaData resultSetMetaData = resultSet.getMetaData();
        List<Integer> actualIndexToExpectedIndexList = checkHeader(resultSetMetaData, "Time,root.ln.wf01.wt01.status,root.ln.wf01.wt01.temperature," + "root.ln.wf02.wt02.hardware,root.ln.wf02.wt02.status,root.sgcc.wf03.wt01.status," + "root.sgcc.wf03.wt01.temperature,", new int[] { Types.TIMESTAMP, Types.BOOLEAN, Types.FLOAT, Types.VARCHAR, Types.BOOLEAN, Types.BOOLEAN, Types.FLOAT });
        int cnt = 0;
        while (resultSet.next()) {
            String[] expectedStrings = retArray[cnt].split(",");
            StringBuilder expectedBuilder = new StringBuilder();
            StringBuilder actualBuilder = new StringBuilder();
            for (int i = 1; i <= resultSetMetaData.getColumnCount(); i++) {
                actualBuilder.append(resultSet.getString(i)).append(",");
                expectedBuilder.append(expectedStrings[actualIndexToExpectedIndexList.get(i - 1)]).append(",");
            }
            Assert.assertEquals(expectedBuilder.toString(), actualBuilder.toString());
            cnt++;
        }
        Assert.assertEquals(10, cnt);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

