                expectedBuilder.append(expectedStrings[actualIndexToExpectedIndexList.get(i - 1)]).append(",");
            }
            Assert.assertEquals(expectedBuilder.toString(), actualBuilder.toString());
            cnt++;
        }
        Assert.assertEquals(5, cnt);
