@Test
public void intAndLongConversionTest() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("insert into root.t1.wf01.wt01(timestamp, status, type, grade) values (1000, true, 1, 1000)");
        statement.execute("insert into root.t1.wf01.wt01(timestamp, status, type, grade) values (2000, false, 2, 2000)");
        try (ResultSet resultSet1 = statement.executeQuery("select count(status) from root.t1.wf01.wt01")) {
            resultSet1.next();
            // type of r1 is INT64(long), test long convert to int
            int countStatus = resultSet1.getInt(1);
            Assert.assertEquals(2L, countStatus);
        }
        try (ResultSet resultSet2 = statement.executeQuery("select type from root.t1.wf01.wt01 where time = 1000 limit 1")) {
            resultSet2.next();
            // type of r2 is INT32(int), test int convert to long
            long type = resultSet2.getLong(2);
            Assert.assertEquals(1, type);
        }
        try (ResultSet resultSet3 = statement.executeQuery("select grade from root.t1.wf01.wt01 where time = 1000 limit 1")) {
            resultSet3.next();
            // type of r3 is INT64(long), test long convert to int
            int grade = resultSet3.getInt(2);
            Assert.assertEquals(1000, grade);
        }
    } catch (SQLException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

