@Test
public void testClusterSchemaQuota() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        try {
            statement.execute("create timeseries root.sg1.d3.s0 with datatype=FLOAT, encoding=RLE, compression=SNAPPY");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("The current metadata capacity has exceeded the cluster quota"));
        }
        try {
            statement.execute("create timeseries of device template on root.sg2.d2;");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("The current metadata capacity has exceeded the cluster quota"));
        }
        // delete some timeseries and database
        statement.execute("delete database root.sg2;");
        statement.execute("delete timeseries root.sg1.d0.s0;");
        // wait heartbeat
        Thread.sleep(2000);
        // now we can create 3 new timeseries or 1 new device
        statement.execute("SET DEVICE TEMPLATE t1 TO root.sg1.d4");
        statement.execute("create timeseries of device template on root.sg1.d4");
        statement.execute("create timeseries root.sg1.d1.s3 with datatype=FLOAT, encoding=RLE, compression=SNAPPY");
        // wait heartbeat
        Thread.sleep(2000);
        try {
            statement.execute("create timeseries root.sg1.d3.s0 with datatype=FLOAT, encoding=RLE, compression=SNAPPY");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("The current metadata capacity has exceeded the cluster quota"));
        }
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail(e.getMessage());
    }
}

