@Test
public void testCreateTemplateAndCreateTimeseries() throws SQLException {
    // test create device template repeatedly
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        // test datatype and encoding check
        try {
            statement.execute("CREATE DEVICE TEMPLATE str1 (s1 TEXT encoding=GORILLA compressor=SNAPPY, s2 INT32)");
            fail();
        } catch (SQLException e) {
            System.out.println(e.getMessage());
            Assert.assertEquals(TSStatusCode.CREATE_TEMPLATE_ERROR.getStatusCode() + ": create template error -encoding GORILLA does not support TEXT", e.getMessage());
        }
        try {
            statement.execute("CREATE DEVICE TEMPLATE t1 (s1 INT64 encoding=RLE compressor=SNAPPY, s2 INT32)");
            fail();
        } catch (SQLException e) {
            Assert.assertEquals(TSStatusCode.METADATA_ERROR.getStatusCode() + ": Duplicated template name: t1", e.getMessage());
        }
        // set device template
        statement.execute("SET DEVICE TEMPLATE t1 TO root.sg1.d1");
        statement.execute("SET DEVICE TEMPLATE t2 TO root.sg1.d2");
        statement.execute("SET DEVICE TEMPLATE t3 TO root.sg1.d3");
        // test drop template which has been set
        try {
            statement.execute("DROP DEVICE TEMPLATE t1");
            fail();
        } catch (SQLException e) {
            Assert.assertEquals(TSStatusCode.METADATA_ERROR.getStatusCode() + ": Template [t1] has been set on MTree, cannot be dropped now.", e.getMessage());
        }
        try (ResultSet resultSet = statement.executeQuery("SHOW TIMESERIES root.sg1.**")) {
            Assert.assertFalse(resultSet.next());
        }
        // create timeseries of device template
        statement.execute("CREATE TIMESERIES OF DEVICE TEMPLATE ON root.sg1.d1");
        statement.execute("CREATE TIMESERIES OF DEVICE TEMPLATE ON root.sg1.d2");
        statement.execute("CREATE TIMESERIES OF DEVICE TEMPLATE ON root.sg1.d3");
        Set<String> expectedResult = new HashSet<>(Arrays.asList("root.sg1.d1.s1,INT64,TS_2DIFF,LZ4", "root.sg1.d1.s2,DOUBLE,GORILLA,LZ4", "root.sg1.d2.s1,INT64,TS_2DIFF,LZ4", "root.sg1.d2.s2,DOUBLE,GORILLA,LZ4", "root.sg1.d3.s1,INT64,TS_2DIFF,LZ4"));
        try (ResultSet resultSet = statement.executeQuery("SHOW TIMESERIES root.sg1.**")) {
            while (resultSet.next()) {
                String actualResult = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.COMPRESSION);
                Assert.assertTrue(expectedResult.contains(actualResult));
                expectedResult.remove(actualResult);
            }
        }
        Assert.assertTrue(expectedResult.isEmpty());
        try (ResultSet resultSet = statement.executeQuery("COUNT TIMESERIES root.sg1.**")) {
            resultSet.next();
            Assert.assertEquals(5, resultSet.getLong(1));
        }
        expectedResult = new HashSet<>(Arrays.asList("root.sg1.d1,false", "root.sg1.d2,true", "root.sg1.d3,true"));
        try (ResultSet resultSet = statement.executeQuery("SHOW DEVICES")) {
            while (resultSet.next()) {
                String actualResult = resultSet.getString(ColumnHeaderConstant.DEVICE) + "," + resultSet.getString(ColumnHeaderConstant.IS_ALIGNED);
                Assert.assertTrue(expectedResult.contains(actualResult));
                expectedResult.remove(actualResult);
            }
        }
        Assert.assertTrue(expectedResult.isEmpty());
        try {
            statement.execute("UNSET DEVICE TEMPLATE t1 FROM root.sg1.d1");
            fail();
        } catch (SQLException e) {
            Assert.assertEquals(TSStatusCode.TEMPLATE_IS_IN_USE.getStatusCode() + ": Template is in use on root.sg1.d1", e.getMessage());
        }
    }
}

