@Test
public void testSizeWindowUDFWithConstants() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        String query = "SELECT accumulator(s1 + 1, 'access'='size', 'windowSize'='1000') FROM root.vehicle.d1";
        try (ResultSet rs = statement.executeQuery(query)) {
            int time = 0;
            int value = 500500;
            for (int i = 0; i < ITERATION_TIMES / 1000; i++) {
                Assert.assertTrue(rs.next());
                Assert.assertEquals(time, rs.getLong(1));
                Assert.assertEquals(value, rs.getLong(2));
                time += 1000;
                value += 1000000;
            }
            Assert.assertFalse(rs.next());
        }
        query = "SELECT 1 + accumulator(s1 + 1, 'access'='size', 'windowSize'='1000') FROM root.vehicle.d1";
        try (ResultSet rs = statement.executeQuery(query)) {
            int time = 0;
            double value = 500501D;
            for (int i = 0; i < ITERATION_TIMES / 1000; i++) {
                Assert.assertTrue(rs.next());
                Assert.assertEquals(time, rs.getLong(1));
                Assert.assertEquals(value, rs.getDouble(2), 0.001);
                time += 1000;
                value += 1000000D;
            }
            Assert.assertFalse(rs.next());
        }
    } catch (SQLException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

