    String sql = "SELECT l.Time_, r.`root.test.flink.lookup.s0`, r.`root.test.flink.lookup.s1`, r.`root.test.flink.lookup.s2`, r.`root.test.flink.lookup.s3`, r.`root.test.flink.lookup.s4`, r.`root.test.flink.lookup.s5`, l.s6 " + "FROM (select *,PROCTIME() as proc_time from leftTable) AS l " + "JOIN rightTable FOR SYSTEM_TIME AS OF l.proc_time AS r " + "ON l.Time_ = r.Time_";
