@Test
public void testExtractorValidParameter() throws Exception {
    DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    String receiverIp = receiverDataNode.getIp();
    int receiverPort = receiverDataNode.getPort();
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        Map<String, String> extractorAttributes = new HashMap<>();
        Map<String, String> processorAttributes = new HashMap<>();
        Map<String, String> connectorAttributes = new HashMap<>();
        extractorAttributes.put("extractor", "iotdb-extractor");
        extractorAttributes.put("extractor.history.enabled", "true");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        // test when start-time and end-time are not set
        TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // test when only extractor.history.start-time is set
        extractorAttributes.put("extractor.history.start-time", "2000.01.01T08:00:00");
        status = client.createPipe(new TCreatePipeReq("p2", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // test when only extractor.history.end-time is set
        extractorAttributes.remove("extractor.history.start-time");
        extractorAttributes.put("extractor.history.end-time", "2000.01.01T08:00:00");
        status = client.createPipe(new TCreatePipeReq("p3", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // test when extractor.history.start-time equals extractor.history.end-time
        extractorAttributes.put("extractor.history.start-time", "2000.01.01T08:00:00");
        status = client.createPipe(new TCreatePipeReq("p4", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // test when extractor.history.start-time is greater than extractor.history.end-time
        extractorAttributes.replace("extractor.history.start-time", "2001.01.01T08:00:00");
        status = client.createPipe(new TCreatePipeReq("p5", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // test when extractor.history.end-time is future time
        extractorAttributes.replace("extractor.history.end-time", "2100.01.01T08:00:00");
        status = client.createPipe(new TCreatePipeReq("p6", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
    }
}

