                senderEnv.shutdownDataNode(i);
                try {
                    TimeUnit.SECONDS.sleep(1);
                } catch (InterruptedException ignored) {
                }
                senderEnv.startDataNode(i);
                ((AbstractEnv) senderEnv).testWorkingNoUnknown();
            }
        }
        if (leaderIndex == -1) {
            // ensure the leader is stopped
            fail();
        }
        TestUtils.executeNonQueryOnSpecifiedDataNodeWithRetry(senderEnv, senderEnv.getDataNodeWrapper(leaderIndex), "insert into root.db.d1(time, s1) values (2, 2)");
