        TestUtils.assertDataOnEnv(receiverEnv, "select count(*) from root.db.d1", "count(root.db.d1.s1),", Collections.singleton("2,"));
    }
    TestUtils.restartCluster(senderEnv);
    TestUtils.restartCluster(receiverEnv);
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        // create a new pipe and write new data
