@Test
public void testDoubleLiving() throws Exception {
    // Double living is two clusters with pipes connecting each other.
    DataNodeWrapper senderDataNode = senderEnv.getDataNodeWrapper(0);
    DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    String senderIp = senderDataNode.getIp();
    int senderPort = senderDataNode.getPort();
    String receiverIp = receiverDataNode.getIp();
    int receiverPort = receiverDataNode.getPort();
    for (int i = 0; i < 100; ++i) {
        TestUtils.executeNonQueryWithRetry(senderEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
    }
    TestUtils.executeNonQueryWithRetry(senderEnv, "flush");
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        Map<String, String> extractorAttributes = new HashMap<>();
        Map<String, String> processorAttributes = new HashMap<>();
        Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
    }
    for (int i = 100; i < 200; ++i) {
        TestUtils.executeNonQueryWithRetry(senderEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
    }
    for (int i = 200; i < 300; ++i) {
        TestUtils.executeNonQueryWithRetry(receiverEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
    }
    TestUtils.executeNonQueryWithRetry(receiverEnv, "flush");
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) receiverEnv.getLeaderConfigNodeConnection()) {
        Map<String, String> extractorAttributes = new HashMap<>();
        Map<String, String> processorAttributes = new HashMap<>();
        Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", senderIp);
        connectorAttributes.put("connector.port", Integer.toString(senderPort));
        TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
    }
    for (int i = 300; i < 400; ++i) {
        TestUtils.executeNonQueryWithRetry(receiverEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
    }
    Set<String> expectedResSet = new HashSet<>();
    for (int i = 0; i < 400; ++i) {
        expectedResSet.add(i + ",1.0,");
    }
    TestUtils.assertDataOnEnv(senderEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
    TestUtils.assertDataOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
    TestUtils.restartCluster(senderEnv);
    TestUtils.restartCluster(receiverEnv);
    for (int i = 400; i < 500; ++i) {
        TestUtils.executeNonQueryWithRetry(senderEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
    }
    TestUtils.executeNonQueryWithRetry(senderEnv, "flush");
    for (int i = 500; i < 600; ++i) {
        TestUtils.executeNonQueryWithRetry(receiverEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
    }
    TestUtils.executeNonQueryWithRetry(receiverEnv, "flush");
    for (int i = 400; i < 600; ++i) {
        expectedResSet.add(i + ",1.0,");
    }
    TestUtils.assertDataOnEnv(senderEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
    TestUtils.assertDataOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
}

