@Test
public void testShowPipeWithWrongPipeName() throws Exception {
    DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    String receiverIp = receiverDataNode.getIp();
    int receiverPort = receiverDataNode.getPort();
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        Map<String, String> extractorAttributes = new HashMap<>();
        Map<String, String> processorAttributes = new HashMap<>();
        Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        status = client.createPipe(new TCreatePipeReq("p2", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        connectorAttributes.replace("connector.batch.enable", "true");
        status = client.createPipe(new TCreatePipeReq("p3", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        List<TShowPipeInfo> showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertEquals(3, showPipeResult.size());
        showPipeResult = client.showPipe(new TShowPipeReq().setPipeName("p1")).pipeInfoList;
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p1")));
        Assert.assertFalse(showPipeResult.stream().anyMatch((o) -> o.id.equals("p2")));
        Assert.assertFalse(showPipeResult.stream().anyMatch((o) -> o.id.equals("p3")));
        // Show all pipes whose connector is also used by p1.
        // p1 and p2 share the same connector parameters, so they have the same connector.
        showPipeResult = client.showPipe(new TShowPipeReq().setPipeName("p1").setWhereClause(true)).pipeInfoList;
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p1")));
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p2")));
        Assert.assertFalse(showPipeResult.stream().anyMatch((o) -> o.id.equals("p3")));
    }
}

