@Test
public void testShowTemplates() throws StatementExecutionException, IoTDBConnectionException, IOException {
    session.setStorageGroup("root.sg");
    Template temp1 = getTemplate("template1");
    Template temp2 = getTemplate("template2");
    assertEquals("[]", session.showAllTemplates().toString());
    session.createSchemaTemplate(temp1);
    session.createSchemaTemplate(temp2);
    assertEquals(new HashSet<>(Arrays.asList("template1", "template2")), new HashSet<>(session.showAllTemplates()));
    session.setSchemaTemplate("template1", "root.sg.v1");
    session.setSchemaTemplate("template1", "root.sg.v2");
    session.setSchemaTemplate("template1", "root.sg.v3");
    assertEquals(new HashSet<>(Arrays.asList("root.sg.v1", "root.sg.v2", "root.sg.v3")), new HashSet<>(session.showPathsTemplateSetOn("template1")));
    assertEquals(new HashSet<>(Collections.emptyList()), new HashSet<>(session.showPathsTemplateUsingOn("template1")));
    session.setSchemaTemplate("template2", "root.sg.v4");
    session.setSchemaTemplate("template2", "root.sg.v5");
    session.setSchemaTemplate("template2", "root.sg.v6");
    assertEquals(new HashSet<>(Arrays.asList("root.sg.v4", "root.sg.v5", "root.sg.v6")), new HashSet<>(session.showPathsTemplateSetOn("template2")));
    assertEquals(new HashSet<>(Arrays.asList("root.sg.v1", "root.sg.v2", "root.sg.v3", "root.sg.v4", "root.sg.v5", "root.sg.v6")), new HashSet<>(session.showPathsTemplateSetOn("*")));
    session.insertRecord("root.sg.v1.GPS", 110L, Collections.singletonList("x"), Collections.singletonList(TSDataType.FLOAT), Collections.singletonList(1.0f));
    assertEquals(new HashSet<>(Collections.singletonList("root.sg.v1.GPS")), new HashSet<>(session.showPathsTemplateUsingOn("template1")));
    session.insertRecord("root.sg.v5.GPS", 110L, Collections.singletonList("x"), Collections.singletonList(TSDataType.FLOAT), Collections.singletonList(1.0f));
    assertEquals(new HashSet<>(Collections.singletonList("root.sg.v1.GPS")), new HashSet<>(session.showPathsTemplateUsingOn("template1")));
    assertEquals(new HashSet<>(Collections.singletonList("root.sg.v5.GPS")), new HashSet<>(session.showPathsTemplateUsingOn("template2")));
}

@Test
public void testDropTemplate() throws StatementExecutionException, IoTDBConnectionException, IOException {
    session.setStorageGroup("root.sg");
    Template temp1 = getTemplate("template1");
    assertEquals("[]", session.showAllTemplates().toString());
    session.createSchemaTemplate(temp1);
    assertEquals("[]", session.showPathsTemplateSetOn("template1").toString());
    try {
        session.createSchemaTemplate(temp1);
        fail();
    } catch (Exception e) {
        assertEquals(TSStatusCode.METADATA_ERROR.getStatusCode() + ": Duplicated template name: template1", e.getMessage());
    }
    session.dropSchemaTemplate("template1");
    session.createSchemaTemplate(temp1);
    session.setSchemaTemplate("template1", "root.sg.v1");
    try {
        session.dropSchemaTemplate("template1");
        fail();
    } catch (Exception e) {
        assertEquals(TSStatusCode.METADATA_ERROR.getStatusCode() + ": Template [template1] has been set on MTree, cannot be dropped now.", e.getMessage());
    }
    session.unsetSchemaTemplate("root.sg.v1", "template1");
    session.dropSchemaTemplate("template1");
    session.createSchemaTemplate(temp1);
}

