@Test
public void testDepAuthorPlan() throws TException, AuthException, IllegalPathException {
    AuthorPlan authorPlan;
    TSStatus status;
    cleanUserAndRole();
    // After authNonQuery, preVersion tag must be false;
    /*--TEST FOR USER CREATE 、UPDATE AND DROP -*/
    // this operation will success for pre version.
    {
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateUserDep, "user1", "", "password1", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
        // this operation will success for pre version. --length~(32,64)
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateUserDep, "user1234567user1234567user1234567user1234567", "", "password1", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
        // this operation will fail for pre version. --length > 64
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateUserDep, "user1234567user1234567user1234567user1234567user1234567user1234567user1234567user1234567", "", "password1", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.ILLEGAL_PARAMETER.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
        // this operation will fail for pre version. -- contain &%*@
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateUserDep, "user1*&%", "", "password1", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.ILLEGAL_PARAMETER.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
        // root, user1, user1234567user1234567user1234567user1234567
        Assert.assertEquals(3, authorInfo.executeListUsers(new AuthorPlan(ConfigPhysicalPlanType.ListUser, "", "", "", "", new HashSet<>(), false, new ArrayList<>())).getMemberList().size());
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.DropUserDep, "user1234567user1234567user1234567user1234567", "", "", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
        Assert.assertEquals(2, authorInfo.executeListUsers(new AuthorPlan(ConfigPhysicalPlanType.ListUserDep, "", "", "", "", new HashSet<>(), false, new ArrayList<>())).getMemberList().size());
        // for pre version, password with &% will meet error.
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.UpdateUserDep, "user1", "", "password*&S", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.ILLEGAL_PARAMETER.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
        /*--TEST FOR ROLE CREATE AND DROP -*/
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateRoleDep, "", "role1", "", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forRolePreVersion());
        // name longer than 32, It's ok.
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateRoleDep, "", "role1234567role1234567role1234567role1234567", "", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forRolePreVersion());
        // contain wrong character, error.
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.CreateRoleDep, "", "role1234567role1%%234567role1234567role1234567", "", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.ILLEGAL_PARAMETER.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forRolePreVersion());
        authorPlan = new AuthorPlan(ConfigPhysicalPlanType.DropRoleDep, "", "role1234567role1234567role1234567role1234567", "", "", new HashSet<>(), false, new ArrayList<>());
        status = authorInfo.authorNonQuery(authorPlan);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertFalse(BasicAuthorizer.getInstance().forRolePreVersion());
        Assert.assertEquals(1, authorInfo.executeListRoles(new AuthorPlan(ConfigPhysicalPlanType.ListRoleDep, "", "", "", "", new HashSet<>(), false, new ArrayList<>())).getMemberList().size());
    }
    // NOW WE HAVE USER：user1， root; ROLE: role1
    for (PriPrivilegeType item : PriPrivilegeType.values()) {
        /*-- TEST IGNORE PRIVILEGES --*/
        if (!item.isAccept()) {
            // for user to grant
            authorPlan = new AuthorPlan(ConfigPhysicalPlanType.GrantUserDep, "user1", "", "", "", Collections.singleton(item.ordinal()), false, new ArrayList<>());
            status = authorInfo.authorNonQuery(authorPlan);
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getPathPrivilegeList().size());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getSysPrivilege().size());
            Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
            // for role to grant
            authorPlan = new AuthorPlan(ConfigPhysicalPlanType.GrantRoleDep, "", "role1", "", "", Collections.singleton(item.ordinal()), false, new ArrayList<>());
            status = authorInfo.authorNonQuery(authorPlan);
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getRole("role1").getPathPrivilegeList().size());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getRole("role1").getSysPrivilege().size());
            Assert.assertFalse(BasicAuthorizer.getInstance().forRolePreVersion());
            // for user to revoke
            authorPlan = new AuthorPlan(ConfigPhysicalPlanType.RevokeUserDep, "user1", "", "", "", Collections.singleton(item.ordinal()), false, new ArrayList<>());
            status = authorInfo.authorNonQuery(authorPlan);
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getPathPrivilegeList().size());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getSysPrivilege().size());
            Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
            // for role to revoke
            authorPlan = new AuthorPlan(ConfigPhysicalPlanType.RevokeRoleDep, "", "role1", "", "", Collections.singleton(item.ordinal()), false, new ArrayList<>());
            status = authorInfo.authorNonQuery(authorPlan);
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getRole("role1").getPathPrivilegeList().size());
            Assert.assertEquals(0, BasicAuthorizer.getInstance().getRole("role1").getSysPrivilege().size());
            Assert.assertFalse(BasicAuthorizer.getInstance().forRolePreVersion());
        } else {
            if (item.isPreIsPathRelevant()) {
                authorPlan = new AuthorPlan(ConfigPhysicalPlanType.GrantUserDep, "user1", "", "", "", Collections.singleton(item.ordinal()), false, Collections.singletonList(new PartialPath("root.t1.*.t2")));
                status = authorInfo.authorNonQuery(authorPlan);
                Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
                if (item.isPathRelevant()) {
                    Assert.assertEquals(1, BasicAuthorizer.getInstance().getUser("user1").getPathPrivileges(new PartialPath("root.t1.*.t2")).size());
                    Assert.assertTrue(BasicAuthorizer.getInstance().getUser("user1").getPathPrivileges(new PartialPath("root.t1.*.t2")).containsAll(item.getSubPriOrd()));
                    Assert.assertFalse(BasicAuthorizer.getInstance().getUser("user1").getServiceReady());
                } else {
                    Assert.assertTrue(BasicAuthorizer.getInstance().getUser("user1").getSysPrivilege().containsAll(item.getSubPriOrd()));
                }
                Assert.assertFalse(BasicAuthorizer.getInstance().forUserPreVersion());
                authorInfo.checkUserPathPrivilege();
                // path will turn to root.t1.**
                authorPlan = new AuthorPlan(ConfigPhysicalPlanType.RevokeUserDep, "user1", "", "", "", Collections.singleton(item.ordinal()), false, Collections.singletonList(new PartialPath("root.t1.**")));
                status = authorInfo.authorNonQuery(authorPlan);
                Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
                if (item.isPathRelevant()) {
                    Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getPathPrivileges(new PartialPath("root.t1.**")).size());
                } else {
                    Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getSysPrivilege().size());
                }
            } else {
                authorPlan = new AuthorPlan(ConfigPhysicalPlanType.GrantUserDep, "user1", "", "", "", Collections.singleton(item.ordinal()), false, Collections.emptyList());
                status = authorInfo.authorNonQuery(authorPlan);
                Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
                Assert.assertTrue(BasicAuthorizer.getInstance().getUser("user1").getSysPrivilege().containsAll(item.getSubSysPriOrd()));
                authorPlan = new AuthorPlan(ConfigPhysicalPlanType.RevokeUserDep, "user1", "", "", "", Collections.singleton(item.ordinal()), false, Collections.emptyList());
                status = authorInfo.authorNonQuery(authorPlan);
                Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
                Assert.assertEquals(0, BasicAuthorizer.getInstance().getUser("user1").getPathPrivileges(new PartialPath("root.t1.**")).size());
            }
        }
    }
}

