@Test
public void testSerialization() throws Exception {
    PartialPath[] pathList = new PartialPath[] { new PartialPath("root.sg"), new PartialPath("root.a.sg"), new PartialPath("root.a.b.sg"), new PartialPath("root.a.a.b.sg") };
    for (int i = 0; i < pathList.length; i++) {
        root.setStorageGroup(pathList[i]);
        IDatabaseMNode<IConfigMNode> storageGroupMNode = root.getDatabaseNodeByDatabasePath(pathList[i]);
        storageGroupMNode.setDataTTL(i);
        storageGroupMNode.getAsMNode().getDatabaseSchema().setDataReplicationFactor(i);
        storageGroupMNode.getAsMNode().getDatabaseSchema().setSchemaReplicationFactor(i);
        storageGroupMNode.getAsMNode().getDatabaseSchema().setTimePartitionInterval(i);
        root.getNodeWithAutoCreate(pathList[i].concatNode("a")).setSchemaTemplateId(i);
    }
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    root.serialize(outputStream);
    ConfigMTree newTree = new ConfigMTree();
    ByteArrayInputStream inputStream = new ByteArrayInputStream(outputStream.toByteArray());
    newTree.deserialize(inputStream);
    for (int i = 0; i < pathList.length; i++) {
        TDatabaseSchema storageGroupSchema = newTree.getDatabaseNodeByDatabasePath(pathList[i]).getAsMNode().getDatabaseSchema();
        Assert.assertEquals(i, storageGroupSchema.getTTL());
        Assert.assertEquals(i, storageGroupSchema.getSchemaReplicationFactor());
        Assert.assertEquals(i, storageGroupSchema.getDataReplicationFactor());
        Assert.assertEquals(i, storageGroupSchema.getTimePartitionInterval());
        assertEquals(i, newTree.getNodeWithAutoCreate(pathList[i].concatNode("a")).getSchemaTemplateId());
    }
    assertEquals(3, newTree.getMatchedDatabases(new PartialPath("root.**.sg"), ALL_MATCH_SCOPE, false).size());
    assertEquals(2, newTree.getMatchedDatabases(new PartialPath("root.**.b.sg"), ALL_MATCH_SCOPE, false).size());
    assertEquals(1, newTree.getMatchedDatabases(new PartialPath("root.*.*.sg"), ALL_MATCH_SCOPE, false).size());
}

