@Test
public void testBasicReadPut() {
    DualKeyCacheBuilder<String, String, String> dualKeyCacheBuilder = new DualKeyCacheBuilder<>();
    IDualKeyCache<String, String, String> dualKeyCache = dualKeyCacheBuilder.cacheEvictionPolicy(DualKeyCachePolicy.valueOf(policy)).memoryCapacity(300).firstKeySizeComputer(this::computeStringSize).secondKeySizeComputer(this::computeStringSize).valueSizeComputer(this::computeStringSize).build();
    String[] firstKeyList = new String[] { "root.db.d1", "root.db.d2" };
    String[] secondKeyList = new String[] { "s1", "s2" };
    String[][] valueTable = new String[][] { new String[] { "1-1", "1-2" }, new String[] { "2-1", "2-2" } };
    for (int i = 0; i < firstKeyList.length; i++) {
        for (int j = 0; j < secondKeyList.length; j++) {
            dualKeyCache.put(firstKeyList[i], secondKeyList[j], valueTable[i][j]);
        }
    }
    int firstKeyOfMissingEntry = -1, secondKeyOfMissingEntry = -1;
    for (int i = 0; i < firstKeyList.length; i++) {
        for (int j = 0; j < secondKeyList.length; j++) {
            String value = dualKeyCache.get(firstKeyList[i], secondKeyList[j]);
            if (value == null) {
                if (firstKeyOfMissingEntry == -1) {
                    firstKeyOfMissingEntry = i;
                    secondKeyOfMissingEntry = j;
                } else {
                    Assert.fail();
                }
            } else {
                Assert.assertEquals(valueTable[i][j], value);
            }
        }
    }
    Assert.assertEquals(230, dualKeyCache.stats().memoryUsage());
    Assert.assertEquals(4, dualKeyCache.stats().requestCount());
    Assert.assertEquals(3, dualKeyCache.stats().hitCount());
    dualKeyCache.put(firstKeyList[firstKeyOfMissingEntry], secondKeyList[secondKeyOfMissingEntry], valueTable[firstKeyOfMissingEntry][secondKeyOfMissingEntry]);
    Assert.assertEquals(230, dualKeyCache.stats().memoryUsage());
    for (int i = 0; i < firstKeyList.length; i++) {
        int finalI = i;
        dualKeyCache.compute(new IDualKeyCacheComputation<String, String, String>() {

            @Override
            public String getFirstKey() {
                return firstKeyList[finalI];
            }

            @Override
            public String[] getSecondKeyList() {
                return secondKeyList;
            }

            @Override
            public void computeValue(int index, String value) {
                if (value != null) {
                    Assert.assertEquals(valueTable[finalI][index], value);
                }
            }
        });
    }
    Assert.assertEquals(8, dualKeyCache.stats().requestCount());
    Assert.assertEquals(6, dualKeyCache.stats().hitCount());
}

@Test
public void testComputeAndUpdateSize() {
    DualKeyCacheBuilder<String, String, SchemaCacheEntry> dualKeyCacheBuilder = new DualKeyCacheBuilder<>();
    IDualKeyCache<String, String, SchemaCacheEntry> dualKeyCache = dualKeyCacheBuilder.cacheEvictionPolicy(DualKeyCachePolicy.valueOf(policy)).memoryCapacity(500).firstKeySizeComputer(this::computeStringSize).secondKeySizeComputer(this::computeStringSize).valueSizeComputer(SchemaCacheEntry::estimateSize).build();
    String firstKey = "root.db.d1";
    String[] secondKeyList = new String[] { "s1", "s2" };
    for (String s : secondKeyList) {
        dualKeyCache.put(firstKey, s, new SchemaCacheEntry("root.db", new MeasurementSchema(s, TSDataType.INT32), Collections.emptyMap(), false));
    }
    SchemaCacheEntry schemaCacheEntry = new SchemaCacheEntry("root.db", new MeasurementSchema("s1", TSDataType.INT32), Collections.emptyMap(), false);
    int expectedSize = computeStringSize("root.db.d1") + computeStringSize("s1") * 2 + SchemaCacheEntry.estimateSize(schemaCacheEntry) * 2;
    Assert.assertEquals(expectedSize, dualKeyCache.stats().memoryUsage());
    dualKeyCache.update(new IDualKeyCacheUpdating<String, String, SchemaCacheEntry>() {

        @Override
        public String getFirstKey() {
            return firstKey;
        }

        @Override
        public String[] getSecondKeyList() {
            return secondKeyList;
        }

        @Override
        public int updateValue(int index, SchemaCacheEntry value) {
            return DataNodeLastCacheManager.updateLastCache(value, new TimeValuePair(1L, new TsPrimitiveType.TsInt(1)), true, 0L);
        }
    });
    int tmp = SchemaCacheEntry.estimateSize(schemaCacheEntry);
    schemaCacheEntry.updateLastCache(new TimeValuePair(1L, new TsPrimitiveType.TsInt(1)), true, 0L);
    expectedSize += (SchemaCacheEntry.estimateSize(schemaCacheEntry) - tmp) * 2;
    Assert.assertEquals(expectedSize, dualKeyCache.stats().memoryUsage());
}

