@Test
public void stringAppendPatternTreeMapTest() throws IllegalPathException {
    PatternTreeMap<String, StringSerializer> patternTreeMap = PatternTreeMapFactory.getTriggerPatternTreeMap();
    patternTreeMap.append(new PartialPath("root.sg1.d1.s1"), "A");
    patternTreeMap.append(new PartialPath("root.**.s1"), "B");
    patternTreeMap.append(new PartialPath("root.sg1.*.s1"), "C");
    patternTreeMap.append(new PartialPath("root.sg1.d1.s1"), "D");
    patternTreeMap.append(new PartialPath("root.sg1.**"), "E");
    patternTreeMap.append(new PartialPath("root.sg1.**.s2"), "F");
    patternTreeMap.append(new PartialPath("root.**.d1.*"), "G");
    patternTreeMap.append(new PartialPath("root.**.d1.**"), "H");
    patternTreeMap.append(new PartialPath("root.*.d1.**"), "I");
    patternTreeMap.append(new PartialPath("root.**"), "J");
    patternTreeMap.append(new PartialPath("root.**.**"), "K");
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s1"), Arrays.asList("A", "B", "C", "D", "E", "G", "H", "I", "J", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg2.s1"), Arrays.asList("B", "J", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s2"), Arrays.asList("E", "F", "G", "H", "I", "J", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.v1.s1"), Arrays.asList("B", "E", "H", "I", "J", "K"));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d1"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("A", "B", "C", "D", "E", "G", "H", "I", "J", "K"), Arrays.asList("E", "F", "G", "H", "I", "J", "K")));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d2"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("B", "C", "E", "J", "K"), Arrays.asList("E", "F", "J", "K")));
    // delete leaf node with common parent
    patternTreeMap.delete(new PartialPath("root.**.d1.*"), "G");
    // only delete value, no delete leaf node
    patternTreeMap.delete(new PartialPath("root.sg1.d1.s1"), "D");
    // delete internal node
    patternTreeMap.delete(new PartialPath("root.**"), "J");
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s1"), Arrays.asList("A", "B", "C", "E", "H", "I", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s2"), Arrays.asList("E", "F", "H", "I", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.v1.s1"), Arrays.asList("B", "E", "H", "I", "K"));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d1"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("A", "B", "C", "E", "H", "I", "K"), Arrays.asList("E", "F", "H", "I", "K")));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d2"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("B", "C", "E", "K"), Arrays.asList("E", "F", "K")));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.v1.d1"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("B", "E", "H", "K"), Arrays.asList("E", "F", "H", "K")));
}

