@Test
public void testGetMatchedDevices() throws Exception {
    ISchemaRegion schemaRegion = getSchemaRegion("root.laptop", 0);
    SchemaRegionTestUtil.createSimpleTimeseriesByList(schemaRegion, Arrays.asList("root.laptop.d0", "root.laptop.d1.s1", "root.laptop.d1.s2.t1", "root.laptop.d1.s3", "root.laptop.d2.s1", "root.laptop.d2.s2"));
    // CASE 01. Query a timeseries, result should be empty set.
    Assert.assertEquals(Collections.emptyList(), SchemaRegionTestUtil.getMatchedDevices(schemaRegion, new PartialPath("root.laptop.d0")));
    // CASE 02. Query an existing device.
    Assert.assertEquals(Collections.singletonList(new ShowDevicesResult("root.laptop.d1", false)), SchemaRegionTestUtil.getMatchedDevices(schemaRegion, new PartialPath("root.laptop.d1")));
    Assert.assertEquals(Collections.singletonList(new ShowDevicesResult("root.laptop.d2", false)), SchemaRegionTestUtil.getMatchedDevices(schemaRegion, new PartialPath("root.laptop.d2")));
    // CASE 03. Query an existing device, which has a sub device
    Assert.assertEquals(Collections.singletonList(new ShowDevicesResult("root.laptop", false)), SchemaRegionTestUtil.getMatchedDevices(schemaRegion, new PartialPath("root.laptop")));
    // CASE 04. Query devices using '*'
    Assert.assertEquals(Collections.singletonList(new ShowDevicesResult("root.laptop", false)), SchemaRegionTestUtil.getMatchedDevices(schemaRegion, new PartialPath("root.*")));
    // CASE 05. Query all devices using 'root.**'
    List<IDeviceSchemaInfo> expectedList = Arrays.asList(new ShowDevicesResult("root.laptop", false), new ShowDevicesResult("root.laptop.d1", false), new ShowDevicesResult("root.laptop.d2", false), new ShowDevicesResult("root.laptop.d1.s2", false));
    List<IDeviceSchemaInfo> actualResult = SchemaRegionTestUtil.getMatchedDevices(schemaRegion, new PartialPath("root.**"));
    // Compare hash sets because the order does not matter.
    HashSet<IDeviceSchemaInfo> expectedHashset = new HashSet<>(expectedList);
    HashSet<IDeviceSchemaInfo> actualHashset = new HashSet<>(actualResult);
    Assert.assertEquals(expectedHashset, actualHashset);
    // CASE 06. show devices root.**.d*
    expectedList = Arrays.asList(new ShowDevicesResult("root.laptop.d1", false), new ShowDevicesResult("root.laptop.d2", false));
