@Test
public void testRatisModeSnapshot() throws Exception {
    String schemaRegionConsensusProtocolClass = config.getSchemaRegionConsensusProtocolClass();
    config.setSchemaRegionConsensusProtocolClass(ConsensusFactory.RATIS_CONSENSUS);
    try {
        ISchemaRegion schemaRegion = getSchemaRegion("root.sg", 0);
        File mLogFile = SystemFileFactory.INSTANCE.getFile(schemaRegion.getDatabaseFullPath() + File.separator + schemaRegion.getSchemaRegionId().getId(), SchemaConstant.METADATA_LOG);
        Assert.assertFalse(mLogFile.exists());
        Map<String, String> tags = new HashMap<>();
        tags.put("tag-key", "tag-value");
        schemaRegion.createTimeseries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.d1.s1"), TSDataType.INT32, TSEncoding.PLAIN, CompressionType.UNCOMPRESSED, null, tags, null, null), -1);
        Template template = generateTemplate();
        schemaRegion.activateSchemaTemplate(SchemaRegionWritePlanFactory.getActivateTemplateInClusterPlan(new PartialPath("root.sg.d2"), 1, template.getId()), template);
        File snapshotDir = new File(config.getSchemaDir() + File.separator + "snapshot");
        snapshotDir.mkdir();
        schemaRegion.createSnapshot(snapshotDir);
        schemaRegion.loadSnapshot(snapshotDir);
        List<ITimeSeriesSchemaInfo> result = SchemaRegionTestUtil.showTimeseries(schemaRegion, new PartialPath("root.sg.**"), false, "tag-key", "tag-value");
        ITimeSeriesSchemaInfo seriesResult = result.get(0);
        Assert.assertEquals(new PartialPath("root.sg.d1.s1").getFullPath(), seriesResult.getFullPath());
        Map<String, String> resultTagMap = seriesResult.getTags();
        Assert.assertEquals(1, resultTagMap.size());
        Assert.assertEquals("tag-value", resultTagMap.get("tag-key"));
        simulateRestart();
        ISchemaRegion newSchemaRegion = getSchemaRegion("root.sg", 0);
        newSchemaRegion.loadSnapshot(snapshotDir);
        result = SchemaRegionTestUtil.showTimeseries(newSchemaRegion, new PartialPath("root.sg.**"), false, "tag-key", "tag-value");
        seriesResult = result.get(0);
        Assert.assertEquals(new PartialPath("root.sg.d1.s1").getFullPath(), seriesResult.getFullPath());
        resultTagMap = seriesResult.getTags();
        Assert.assertEquals(1, resultTagMap.size());
        Assert.assertEquals("tag-value", resultTagMap.get("tag-key"));
        result = SchemaRegionTestUtil.showTimeseries(newSchemaRegion, new PartialPath("root.sg.*.s1"), Collections.singletonMap(template.getId(), template));
        result.sort(Comparator.comparing(ISchemaInfo::getFullPath));
        Assert.assertEquals(new PartialPath("root.sg.d1.s1").getFullPath(), result.get(0).getFullPath());
        Assert.assertEquals(new PartialPath("root.sg.d2.s1").getFullPath(), result.get(1).getFullPath());
    } finally {
        config.setSchemaRegionConsensusProtocolClass(schemaRegionConsensusProtocolClass);
    }
}

