        List<Future<?>> listenFutures = Arrays.asList(listen(extractors[0], event -> event instanceof TabletInsertionEvent ? 1 : 2, writeNum << 1), listen(extractors[1], event -> 1, writeNum));
        try {
            listenFutures.get(0).get(10, TimeUnit.MINUTES);
            listenFutures.get(1).get(10, TimeUnit.MINUTES);
        } catch (TimeoutException e) {
            LOGGER.warn("Time out when listening extractor", e);
            alive.set(false);
            Assert.fail();
        }
        writeFutures.forEach(future -> {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        });
        // start extractor 2, 3
        extractors[2].start();
        extractors[3].start();
        // test result of extractor 0 - 3
        writeFutures = Arrays.asList(write2DataRegion(writeNum, dataRegion1, writeNum), write2DataRegion(writeNum, dataRegion2, writeNum));
        alive.set(true);
        listenFutures = Arrays.asList(listen(extractors[0], event -> event instanceof TabletInsertionEvent ? 1 : 2, writeNum << 1), listen(extractors[1], event -> 1, writeNum), listen(extractors[2], event -> event instanceof TabletInsertionEvent ? 1 : 2, writeNum << 1), listen(extractors[3], event -> 1, writeNum));
        try {
            listenFutures.get(0).get(10, TimeUnit.MINUTES);
            listenFutures.get(1).get(10, TimeUnit.MINUTES);
            listenFutures.get(2).get(10, TimeUnit.MINUTES);
            listenFutures.get(3).get(10, TimeUnit.MINUTES);
        } catch (TimeoutException e) {
            LOGGER.warn("Time out when listening extractor", e);
            alive.set(false);
            Assert.fail();
        }
        writeFutures.forEach(future -> {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        });
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

