@Test
@Ignore
public void testPerformanceOnComplexTree() throws IllegalPathException {
    int deep = 5;
    int width = 5;
    SchemaNode root = generateComplexSchemaTree(deep, width);
    PartialPath path = new PartialPath("root.**.d0.s");
    long startTime = System.currentTimeMillis();
    long calTime = 0;
    int round = 20;
    for (int i = 0; i < round; i++) {
        for (int j = 0; j < 1000; j++) {
            SchemaTreeVisitorWithLimitOffsetWrapper<MeasurementPath> visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, path, 0, 0, false);
