    checkVisitorResult(visitor, 1, new String[] { "root.c.c.c.d.c.c.s1" }, null, new boolean[] { false });
    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.**.d.*.*"), 0, 0, false);
    checkVisitorResult(visitor, 1, new String[] { "root.c.c.c.d.c.s1" }, null, new boolean[] { false });
}

