    // Construct a mock client.
    SyncDataNodeMPPDataExchangeServiceClient mockClient = Mockito.mock(SyncDataNodeMPPDataExchangeServiceClient.class);
    try {
        Mockito.when(mockClientManager.borrowClient(remoteEndpoint)).thenReturn(mockClient);
        Mockito.doAnswer(invocation -> {
            TGetDataBlockRequest req = invocation.getArgument(0);
            List<ByteBuffer> byteBuffers = new ArrayList<>(req.getEndSequenceId() - req.getStartSequenceId());
            for (int i = 0; i < req.getEndSequenceId() - req.getStartSequenceId(); i++) {
                byteBuffers.add(ByteBuffer.allocate(0));
            }
            return new TGetDataBlockResponse(byteBuffers);
        }).when(mockClient).getDataBlock(Mockito.any(TGetDataBlockRequest.class));
    } catch (ClientManagerException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    SourceHandle sourceHandle = new SourceHandle(remoteEndpoint, remoteFragmentInstanceId, localFragmentInstanceId, localPlanNodeId, 0, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), mockTsBlockSerde, mockSourceHandleListener, mockClientManager);
    Assert.assertFalse(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    // New data blocks event arrived in unordered manner.
    sourceHandle.updatePendingDataBlockInfo(numOfMockTsBlock, Stream.generate(() -> MOCK_TSBLOCK_SIZE).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(0)).getDataBlock(Mockito.any(TGetDataBlockRequest.class));
        Mockito.verify(mockClient, Mockito.timeout(10_0000).times(0)).onAcknowledgeDataBlockEvent(Mockito.any(TAcknowledgeDataBlockEvent.class));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    sourceHandle.updatePendingDataBlockInfo(0, Stream.generate(() -> MOCK_TSBLOCK_SIZE).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && 0 == req.getStartSequenceId() && numOfMockTsBlock * 2 == req.getEndSequenceId()));
        Mockito.verify(mockClient, Mockito.timeout(10_0000).times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && 0 == e.getStartSequenceId() && numOfMockTsBlock * 2 == e.getEndSequenceId()));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(numOfMockTsBlock * 2 * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    // The local fragment instance consumes the data blocks.
    for (int i = 0; i < 2 * numOfMockTsBlock; i++) {
        sourceHandle.receive();
        if (i < 2 * numOfMockTsBlock - 1) {
            Assert.assertTrue(sourceHandle.isBlocked().isDone());
        } else {
            Assert.assertFalse(sourceHandle.isBlocked().isDone());
        }
        Assert.assertFalse(sourceHandle.isAborted());
        Assert.assertFalse(sourceHandle.isFinished());
        Assert.assertEquals((2 * numOfMockTsBlock - 1 - i) * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    }
    // New data blocks event arrived.
    sourceHandle.updatePendingDataBlockInfo(numOfMockTsBlock * 2, Stream.generate(() -> MOCK_TSBLOCK_SIZE).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && numOfMockTsBlock * 2 == req.getStartSequenceId() && numOfMockTsBlock * 3 == req.getEndSequenceId()));
        Mockito.verify(mockClient, Mockito.timeout(10_0000).times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && numOfMockTsBlock * 2 == e.getStartSequenceId() && numOfMockTsBlock * 3 == e.getEndSequenceId()));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(numOfMockTsBlock * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    // The local fragment instance consumes the data blocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        sourceHandle.receive();
        if (i < numOfMockTsBlock - 1) {
            Assert.assertTrue(sourceHandle.isBlocked().isDone());
        } else {
            Assert.assertFalse(sourceHandle.isBlocked().isDone());
        }
        Assert.assertFalse(sourceHandle.isAborted());
        Assert.assertFalse(sourceHandle.isFinished());
        Assert.assertEquals((numOfMockTsBlock - 1 - i) * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    }
    // Receive EndOfDataBlock event from upstream fragment instance.
    sourceHandle.setNoMoreTsBlocks(3 * numOfMockTsBlock - 1);
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertTrue(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    Mockito.verify(mockSourceHandleListener, Mockito.timeout(10_0000).times(1)).onFinished(sourceHandle);
}

