@Test
public void batchTest1() throws Exception {
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    try {
        AlignedPath alignedPath = new AlignedPath(SERIES_SCAN_OPERATOR_TEST_SG + ".device0", measurementSchemas.stream().map(MeasurementSchema::getMeasurementId).collect(Collectors.toList()), measurementSchemas.stream().map(m -> (IMeasurementSchema) m).collect(Collectors.toList()));
        QueryId queryId = new QueryId("stub_query");
        FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(queryId, 0), "stub-instance");
        FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
        FragmentInstanceContext fragmentInstanceContext = createFragmentInstanceContext(instanceId, stateMachine);
        DriverContext driverContext = new DriverContext(fragmentInstanceContext, 0);
        PlanNodeId planNodeId = new PlanNodeId("1");
        driverContext.addOperatorContext(1, planNodeId, AlignedSeriesScanOperator.class.getSimpleName());
        AlignedSeriesScanOperator seriesScanOperator = new AlignedSeriesScanOperator(driverContext.getOperatorContexts().get(0), planNodeId, alignedPath, Ordering.ASC, getDefaultSeriesScanOptions(alignedPath), false);
        seriesScanOperator.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        int count = 0;
        while (seriesScanOperator.hasNext()) {
            TsBlock tsBlock = seriesScanOperator.next();
            assertEquals(6, tsBlock.getValueColumnCount());
            assertTrue(tsBlock.getColumn(0) instanceof BooleanColumn);
            assertTrue(tsBlock.getColumn(1) instanceof IntColumn);
            assertTrue(tsBlock.getColumn(2) instanceof LongColumn);
            assertTrue(tsBlock.getColumn(3) instanceof FloatColumn);
            assertTrue(tsBlock.getColumn(4) instanceof DoubleColumn);
            assertTrue(tsBlock.getColumn(5) instanceof BinaryColumn);
            for (int i = 0; i < tsBlock.getPositionCount(); i++, count++) {
                assertEquals(count, tsBlock.getTimeByIndex(i));
                int delta = 0;
                if ((long) count < 200) {
                    delta = 20000;
                } else if ((long) count < 260 || ((long) count >= 300 && (long) count < 380) || (long) count >= 400) {
                    delta = 10000;
                }
                assertEquals((delta + (long) count) % 2 == 0, tsBlock.getColumn(0).getBoolean(i));
                assertEquals(delta + (long) count, tsBlock.getColumn(1).getInt(i));
                assertEquals(delta + (long) count, tsBlock.getColumn(2).getLong(i));
                assertEquals(delta + (long) count, tsBlock.getColumn(3).getFloat(i), DELTA);
                assertEquals(delta + (long) count, tsBlock.getColumn(4).getDouble(i), DELTA);
                assertEquals(String.valueOf(delta + (long) count), tsBlock.getColumn(5).getBinary(i).toString());
            }
        }
        assertEquals(500, count);
    } catch (IllegalPathException e) {
        e.printStackTrace();
        fail();
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

