            final boolean[][][] isNull = new boolean[][][] { { { false, true, false, false }, { false, false, false, true }, { false, false, true, true }, { true, false, true, true }, { true, true, false, true } }, { { false, true, false, true }, { false, false, false, true }, { false, false, true, false }, { true, false, true, true }, { true, true, false, true } }, { { false, true, false, true }, { false, false, false, false }, { false, false, true, false }, { true, false, true, true }, { true, true, false, true } } };

            @Override
            public OperatorContext getOperatorContext() {
                return driverContext.getOperatorContexts().get(0);
            }

            @Override
            public TsBlock next() throws Exception {
                TsBlockBuilder builder = new TsBlockBuilder(ImmutableList.of(TSDataType.FLOAT, TSDataType.FLOAT, TSDataType.FLOAT, TSDataType.FLOAT));
                for (int i = 0; i < 5; i++) {
                    builder.getTimeColumnBuilder().writeLong(i + index * 5L);
                    for (int j = 0; j < 4; j++) {
                        if (isNull[index][i][j]) {
                            builder.getColumnBuilder(j).appendNull();
                        } else {
                            builder.getColumnBuilder(j).writeFloat(value[index][i][j]);
                        }
                    }
                    builder.declarePosition();
                }
                index++;
                return builder.build();
            }

            @Override
            public boolean hasNext() throws Exception {
                return index < 3;
