            }

            @Override
            public long calculateRetainedSizeAfterCallingNext() {
                return 0;
            }
        });
        int count = 0;
        float[][][] res = new float[][][] { { { 1.0f, 0.0f, 3.0f, 4.0f }, { 11.0f, 12.0f, 13.0f, 39.0f }, { 21.0f, 22.0f, 28.0f, 39.0f }, { 36.0f, 32.0f, 28.0f, 39.0f }, { 36.0f, 47.0f, 43.0f, 39.0f } }, { { 51.0f, 47.0f, 53.0f, 39.0f }, { 61.0f, 62.0f, 63.0f, 39.0f }, { 71.0f, 72.0f, 78.0f, 74.0f }, { 86.0f, 82.0f, 78.0f, 94.0f }, { 86.0f, 97.0f, 93.0f, 94.0f } }, { { 101.0f, 97.0f, 103.0f, 94.0f }, { 111.0f, 112.0f, 113.0f, 114.0f }, { 121.0f, 122.0f, 128.0f, 124.0f }, { 0.0f, 132.0f, 128.0f, 0.0f }, { 0.0f, 0.0f, 143.0f, 0.0f } } };
        boolean[][][] isNull = new boolean[][][] { { { false, true, false, false }, { false, false, false, false }, { false, false, false, false }, { false, false, false, false }, { false, false, false, false } }, { { false, false, false, false }, { false, false, false, false }, { false, false, false, false }, { false, false, false, false }, { false, false, false, false } }, { { false, false, false, false }, { false, false, false, false }, { false, false, false, false }, { true, false, false, true }, { true, true, false, true } } };
        boolean[] nullBlock = new boolean[] { true, false, false, false };
        int nullBlockIndex = 0;
        while (fillOperator.hasNext()) {
            TsBlock block = fillOperator.next();
            assertEquals(nullBlock[nullBlockIndex++], block == null);
            if (block == null) {
                continue;
            }
            for (int i = 0; i < block.getPositionCount(); i++) {
                long expectedTime = i + count * 5L;
                assertEquals(expectedTime, block.getTimeByIndex(i));
                for (int j = 0; j < 4; j++) {
                    assertEquals(isNull[count][i][j], block.getColumn(j).isNull(i));
