public void batchLinearFillBooleanTest() throws Exception {
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    try {
        QueryId queryId = new QueryId("stub_query");
        FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(queryId, 0), "stub-instance");
        FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
        FragmentInstanceContext fragmentInstanceContext = createFragmentInstanceContext(instanceId, stateMachine);
        DriverContext driverContext = new DriverContext(fragmentInstanceContext, 0);
        PlanNodeId planNodeId1 = new PlanNodeId("1");
        driverContext.addOperatorContext(1, planNodeId1, LinearFillOperator.class.getSimpleName());
        ILinearFill[] fillArray = new ILinearFill[] { new IdentityLinearFill() };
        LinearFillOperator fillOperator = new LinearFillOperator(driverContext.getOperatorContexts().get(0), fillArray, new Operator() {

            private int index = 0;

            private final boolean[][][] value = new boolean[][][] { { { true } }, { { true } }, { { false } }, { { false } }, { { true } }, { { false } }, { { true } } };

            final boolean[][][] isNull = new boolean[][][] { { { true } }, { { false } }, { { false } }, { { false } }, { { true } }, { { true } }, { { true } } };

            @Override
            public OperatorContext getOperatorContext() {
                return driverContext.getOperatorContexts().get(0);
            }

            @Override
            public TsBlock next() throws Exception {
                TsBlockBuilder builder = new TsBlockBuilder(ImmutableList.of(TSDataType.BOOLEAN));
                for (int i = 0; i < 1; i++) {
                    builder.getTimeColumnBuilder().writeLong(i + index);
                    for (int j = 0; j < 1; j++) {
                        if (isNull[index][i][j]) {
                            builder.getColumnBuilder(j).appendNull();
                        } else {
                            builder.getColumnBuilder(j).writeBoolean(value[index][i][j]);
                        }
                    }
                    builder.declarePosition();
                }
                index++;
                return builder.build();
            }

            @Override
            public boolean hasNext() throws Exception {
                return index < 7;
            }

            @Override
            public boolean isFinished() throws Exception {
                return index >= 7;
            }

            @Override
            public long calculateMaxPeekMemory() {
                return 0;
            }

            @Override
            public long calculateMaxReturnSize() {
                return 0;
            }

            @Override
            public long calculateRetainedSizeAfterCallingNext() {
                return 0;
            }
        });
        int count = 0;
        boolean[][][] res = new boolean[][][] { { { true } }, { { true } }, { { false } }, { { false } }, { { true } }, { { false } }, { { true } } };
        boolean[][][] isNull = new boolean[][][] { { { true } }, { { false } }, { { false } }, { { false } }, { { true } }, { { true } }, { { true } } };
        while (fillOperator.hasNext()) {
            TsBlock block = fillOperator.next();
            assertNotNull(block);
            for (int i = 0; i < block.getPositionCount(); i++) {
                long expectedTime = i + count;
                assertEquals(expectedTime, block.getTimeByIndex(i));
                for (int j = 0; j < 1; j++) {
                    assertEquals(isNull[count][i][j], block.getColumn(j).isNull(i));
                    if (!isNull[count][i][j]) {
                        assertEquals(res[count][i][j], block.getColumn(j).getBoolean(i));
                    }
                }
            }
            count++;
        }
        assertTrue(fillOperator.isFinished());
        assertEquals(res.length, count);
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

