@Test
public void testCountMergeOperator() {
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    try {
        QueryId queryId = new QueryId("stub_query");
        FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(queryId, 0), "stub-instance");
        FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
        FragmentInstanceContext fragmentInstanceContext = createFragmentInstanceContext(instanceId, stateMachine);
        DriverContext driverContext = new DriverContext(fragmentInstanceContext, 0);
        PlanNodeId planNodeId = queryId.genPlanNodeId();
        OperatorContext operatorContext = driverContext.addOperatorContext(1, planNodeId, CountGroupByLevelScanOperator.class.getSimpleName());
        ISchemaRegion schemaRegion = Mockito.mock(ISchemaRegion.class);
        operatorContext.setDriverContext(new SchemaDriverContext(fragmentInstanceContext, schemaRegion, 0));
        CountGroupByLevelScanOperator<ITimeSeriesSchemaInfo> timeSeriesCountOperator1 = new CountGroupByLevelScanOperator<>(planNodeId, driverContext.getOperatorContexts().get(0), 2, mockSchemaSource(schemaRegion, new PartialPath(OPERATOR_TEST_SG + ".device2"), true));
        CountGroupByLevelScanOperator<ITimeSeriesSchemaInfo> timeSeriesCountOperator2 = new CountGroupByLevelScanOperator<>(planNodeId, driverContext.getOperatorContexts().get(0), 2, mockSchemaSource(schemaRegion, new PartialPath(OPERATOR_TEST_SG), true));
        CountGroupByLevelMergeOperator mergeOperator = new CountGroupByLevelMergeOperator(driverContext.getOperatorContexts().get(0), Arrays.asList(timeSeriesCountOperator1, timeSeriesCountOperator2));
        Assert.assertTrue(mergeOperator.isBlocked().isDone());
        List<TsBlock> tsBlocks = new ArrayList<>();
        while (mergeOperator.hasNext()) {
            TsBlock tsBlock = mergeOperator.next();
            if (tsBlock == null || tsBlock.isEmpty()) {
                continue;
            }
            tsBlocks.add(tsBlock);
        }
        assertFalse(tsBlocks.isEmpty());
        Set<String> pathSet = new HashSet<>(2001);
        for (TsBlock tsBlock : tsBlocks) {
            for (int i = 0; i < tsBlock.getPositionCount(); i++) {
                String path = tsBlock.getColumn(0).getBinary(i).getStringValue();
                pathSet.add(path);
                assertTrue(path.startsWith(OPERATOR_TEST_SG));
                if (path.equals(OPERATOR_TEST_SG + ".device2")) {
                    assertEquals(10, tsBlock.getColumn(1).getLong(i));
                } else {
                    assertEquals(1, tsBlock.getColumn(1).getLong(i));
                }
            }
        }
        Assert.assertEquals(2001, pathSet.size());
    } catch (Exception e) {
        e.printStackTrace();
        fail();
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

