    Assert.assertEquals(3, pair.left.size());
    Assert.assertEquals(Arrays.asList("root.sg.d1.s2", "root.sg.d2.a.s2", "root.sg.d2.s2"), pair.left.stream().map(MeasurementPath::getFullPath).collect(Collectors.toList()));
}

