    AbstractDriverThread executor = new DriverTaskThread("0", new ThreadGroup("timeout-test"), taskQueue, mockScheduler, producer);
    // FINISHED status test
    DriverTask testTask = new DriverTask(mockDriver, 100L, DriverTaskStatus.FINISHED, null, 0, false);
    executor.execute(testTask);
