@Test
public void testRawDataQuery() {
    String sql = "select s1, status, s1 + 1 as t from root.sg.d1 where time > 100 and s2 > 10;";
    try {
        Analysis actualAnalysis = analyzeSQL(sql);
        Analysis expectedAnalysis = new Analysis();
        expectedAnalysis.setGlobalTimeFilter(TimeFilter.gt(100));
        expectedAnalysis.setSelectExpressions(Sets.newHashSet(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new TimeSeriesOperand(new PartialPath("root.sg.d1.s2")), new AdditionExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "1"))));
        expectedAnalysis.setWhereExpression(new GreaterThanExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s2")), new ConstantOperand(TSDataType.INT64, "10")));
        expectedAnalysis.setSourceTransformExpressions(Sets.newHashSet(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new TimeSeriesOperand(new PartialPath("root.sg.d1.s2")), new AdditionExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "1"))));
