        alignByTimeAnalysisEqualTest(actualAnalysis, expectedAnalysis);
        // to test GreaterEqualExpression(>=), NotEqualExpression(!=)
        // with ModuloExpression(%), SubtractionExpression(-),
        // with MultiplicationExpression(*), DivisionExpression(/)
        sql = "select s1, s1/2, s1*3, s1%4, s1-5 from root.sg.d1 " + "where time >= 100 and s2 >= 10 and s2 != 6;";
        actualAnalysis = analyzeSQL(sql);
        expectedAnalysis = new Analysis();
        expectedAnalysis.setGlobalTimeFilter(TimeFilter.gtEq(100));
        expectedAnalysis.setSelectExpressions(Sets.newHashSet(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new DivisionExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "2")), new MultiplicationExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "3")), new ModuloExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "4")), new SubtractionExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "5"))));
        expectedAnalysis.setWhereExpression(new LogicAndExpression(new LogicAndExpression(new ConstantOperand(TSDataType.BOOLEAN, "true"), new GreaterEqualExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s2")), new ConstantOperand(TSDataType.INT64, "10"))), new NonEqualExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s2")), new ConstantOperand(TSDataType.INT64, "6"))));
        expectedAnalysis.setSourceTransformExpressions(Sets.newHashSet(new DivisionExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "2")), new MultiplicationExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "3")), new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ModuloExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "4")), new SubtractionExpression(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new ConstantOperand(TSDataType.INT64, "5"))));
        expectedAnalysis.setSourceExpressions(Sets.newHashSet(new TimeSeriesOperand(new PartialPath("root.sg.d1.s1")), new TimeSeriesOperand(new PartialPath("root.sg.d1.s2"))));
        expectedAnalysis.setRespDatasetHeader(new DatasetHeader(Arrays.asList(new ColumnHeader("root.sg.d1.s1", TSDataType.INT32, null), new ColumnHeader("root.sg.d1.s1 / 2", TSDataType.DOUBLE, null), new ColumnHeader("root.sg.d1.s1 * 3", TSDataType.DOUBLE, null), new ColumnHeader("root.sg.d1.s1 % 4", TSDataType.DOUBLE, null), new ColumnHeader("root.sg.d1.s1 - 5", TSDataType.DOUBLE, null)), false));
        alignByTimeAnalysisEqualTest(actualAnalysis, expectedAnalysis);
    } catch (Exception e) {
