@Test
public void testGetTimePartitionSlotList() {
    // time >= 10 and time <= 9
    Pair<List<TTimePartitionSlot>, Pair<Boolean, Boolean>> res = getTimePartitionSlotList(new AndFilter(TimeFilter.gtEq(10), TimeFilter.ltEq(9)));
    assertTrue(res.left.isEmpty());
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // time >= 10
    res = getTimePartitionSlotList(TimeFilter.gtEq(10));
    assertEquals(1, res.left.size());
    List<TTimePartitionSlot> expected = Collections.singletonList(new TTimePartitionSlot(0));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertTrue(res.right.right);
    // time < 20
    res = getTimePartitionSlotList(TimeFilter.lt(20));
    assertEquals(1, res.left.size());
    expected = Collections.singletonList(new TTimePartitionSlot(0));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertTrue(res.right.left);
    assertFalse(res.right.right);
    // time > 10 and time <= 20
    res = getTimePartitionSlotList(new AndFilter(TimeFilter.gt(10), TimeFilter.ltEq(20)));
    expected = Collections.singletonList(new TTimePartitionSlot(0));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // time > 0 and time <= IoTDBDescriptor.getInstance()
    //                                     .getConfig().getTimePartitionInterval() * 3 + 1
    res = getTimePartitionSlotList(new AndFilter(TimeFilter.gt(0), TimeFilter.ltEq(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 3 + 1)));
    expected = Arrays.asList(new TTimePartitionSlot(0), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 3));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // time >= IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() - 1 and time <
    // IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() + 1
    res = getTimePartitionSlotList(new AndFilter(TimeFilter.gtEq(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() - 1), TimeFilter.lt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() + 1)));
    expected = Arrays.asList(new TTimePartitionSlot(0), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // time between IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() - 1 and
    // time < IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval()
    res = getTimePartitionSlotList(TimeFilter.between(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() - 1, CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()));
    expected = Arrays.asList(new TTimePartitionSlot(0), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // time >= IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() and time <=
    // IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() + 1
    res = getTimePartitionSlotList(new AndFilter(TimeFilter.gtEq(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()), TimeFilter.ltEq(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() + 1)));
    expected = Collections.singletonList(new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // time between IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() and time <=
    // IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() + 1
    res = getTimePartitionSlotList(TimeFilter.between(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval(), CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() + 1));
    expected = Collections.singletonList(new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
    // (time >= 10 and time < IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval())
    // or (time > IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() and time <
    // IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 100)
    // or (time > IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 50 and
    // time <= IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 40)
    // or (time > IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 20 and
    // time <= IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 3 + 10)
    // or (time > IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 5 + 1 and
    // time < IoTDBDescriptor.getInstance().getConfig().getTimePartitionInterval() * 5 + 10)
    OrFilter orFilter1 = new OrFilter(new AndFilter(TimeFilter.gtEq(10), TimeFilter.lt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval())), new AndFilter(TimeFilter.gt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()), TimeFilter.lt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 100)));
    OrFilter orFilter2 = new OrFilter(orFilter1, new AndFilter(TimeFilter.gt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 50), TimeFilter.ltEq(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 40)));
    OrFilter orFilter3 = new OrFilter(orFilter2, new AndFilter(TimeFilter.gt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2 - 20), TimeFilter.ltEq(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 3 + 10)));
    OrFilter orFilter4 = new OrFilter(orFilter3, new AndFilter(TimeFilter.gt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 5 + 1), TimeFilter.lt(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 5 + 10)));
    res = getTimePartitionSlotList(orFilter4);
    expected = Arrays.asList(new TTimePartitionSlot(0), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval()), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 2), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 3), new TTimePartitionSlot(CommonDescriptor.getInstance().getConfig().getTimePartitionInterval() * 5));
    assertEquals(expected.size(), res.left.size());
    for (int i = 0; i < expected.size(); i++) {
        assertEquals(expected.get(i), res.left.get(i));
    }
    assertFalse(res.right.left);
    assertFalse(res.right.right);
}

