public void testMemoryControl() {
    initESTVList(TSDataType.TEXT);
    int byteLengthMin = SerializableList.INITIAL_BYTE_ARRAY_LENGTH_FOR_MEMORY_CONTROL * 2;
    int byteLengthMax = SerializableList.INITIAL_BYTE_ARRAY_LENGTH_FOR_MEMORY_CONTROL * 8;
    Random random = new Random();
    try {
        for (int i = 0; i < ITERATION_TIMES; ++i) {
            if (i % 7 == 0) {
                tvList.putNull(i);
            } else {
                tvList.putBinary(i, Binary.valueOf(generateRandomString(byteLengthMin + random.nextInt(byteLengthMax - byteLengthMin))));
            }
        }
        LayerPointReader reader = tvList.constructPointReaderUsingTrivialEvictionStrategy();
        int index = 0;
        while (reader.next()) {
            if (index % 7 == 0) {
                assertTrue(reader.isCurrentNull());
            } else {
                int length = reader.currentBinary().getLength();
                assertTrue(byteLengthMin <= length && length < byteLengthMax);
            }
            reader.readyForNext();
            index++;
        }
        byteLengthMin = SerializableList.INITIAL_BYTE_ARRAY_LENGTH_FOR_MEMORY_CONTROL * 16;
        byteLengthMax = SerializableList.INITIAL_BYTE_ARRAY_LENGTH_FOR_MEMORY_CONTROL * 32;
        for (int i = 0; i < ITERATION_TIMES; ++i) {
            if (i % 7 == 0) {
                tvList.putNull(i);
            } else {
                tvList.putBinary(i, Binary.valueOf(generateRandomString(byteLengthMin + random.nextInt(byteLengthMax - byteLengthMin))));
            }
        }
        index = 0;
        while (reader.next()) {
            if (index % 7 == 0) {
                assertTrue(reader.isCurrentNull());
            } else {
                int length = reader.currentBinary().getLength();
                assertTrue(byteLengthMin <= length && length < byteLengthMax);
            }
            reader.readyForNext();
            index++;
        }
        byteLengthMin = SerializableList.INITIAL_BYTE_ARRAY_LENGTH_FOR_MEMORY_CONTROL * 256;
        byteLengthMax = SerializableList.INITIAL_BYTE_ARRAY_LENGTH_FOR_MEMORY_CONTROL * 512;
        for (int i = 0; i < ITERATION_TIMES; ++i) {
            if (i % 7 == 0) {
                tvList.putNull(i);
            } else {
                tvList.putBinary(i, Binary.valueOf(generateRandomString(byteLengthMin + random.nextInt(byteLengthMax - byteLengthMin))));
            }
        }
        index = 0;
        while (reader.next()) {
            if (index % 7 == 0) {
                assertTrue(reader.isCurrentNull());
            } else {
                int length = reader.currentBinary().getLength();
                assertTrue(byteLengthMin <= length && length < byteLengthMax);
            }
            reader.readyForNext();
            index++;
        }
        index = 0;
        for (int i = 0; i < 2 * ITERATION_TIMES; ++i) {
            if (i % 7 == 0) {
                tvList.putNull(i);
            } else {
                tvList.putBinary(i, Binary.valueOf(generateRandomString(byteLengthMin + random.nextInt(byteLengthMax - byteLengthMin))));
            }
            reader.next();
            if (index % 7 == 0) {
                assertTrue(reader.isCurrentNull());
            } else {
                int length = reader.currentBinary().getLength();
                assertTrue(byteLengthMin <= length && length < byteLengthMax);
            }
            reader.readyForNext();
            index++;
        }
        assertEquals(ITERATION_TIMES * 5, tvList.size());
    } catch (QueryProcessException | IOException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testPutAndGetRandomly() {
    cache.set(0, 0);
    Assert.assertEquals(0, cache.get(0));
    cache.set(4, 4);
    Assert.assertEquals(4, cache.get(4));
    cache.set(10, 10);
    Assert.assertEquals(10, cache.get(10));
    Assert.assertEquals(0, cache.get(0));
    Assert.assertEquals(4, cache.get(4));
    Assert.assertEquals(10, cache.get(10));
    cache.set(DATA_SIZE - 1, DATA_SIZE - 1);
    Assert.assertEquals(DATA_SIZE - 1, cache.get(DATA_SIZE - 1));
    cache.set(DATA_SIZE - CACHE_SIZE, DATA_SIZE - CACHE_SIZE);
    Assert.assertEquals(DATA_SIZE - CACHE_SIZE, cache.get(DATA_SIZE - CACHE_SIZE));
    cache.set(DATA_SIZE - 2 * CACHE_SIZE, DATA_SIZE - 2 * CACHE_SIZE);
    Assert.assertEquals(DATA_SIZE - 2 * CACHE_SIZE, cache.get(DATA_SIZE - 2 * CACHE_SIZE));
    Assert.assertEquals(DATA_SIZE - 1, cache.get(DATA_SIZE - 1));
    Assert.assertEquals(DATA_SIZE - CACHE_SIZE, cache.get(DATA_SIZE - CACHE_SIZE));
    Assert.assertEquals(DATA_SIZE - 2 * CACHE_SIZE, cache.get(DATA_SIZE - 2 * CACHE_SIZE));
    Assert.assertEquals(0, cache.get(0));
    Assert.assertEquals(4, cache.get(4));
    Assert.assertEquals(10, cache.get(10));
    cache.set(1, 1);
    Assert.assertEquals(1, cache.get(1));
    cache.set(3, 3);
    Assert.assertEquals(3, cache.get(3));
    Assert.assertEquals(DATA_SIZE - 1, cache.get(DATA_SIZE - 1));
    Assert.assertEquals(DATA_SIZE - CACHE_SIZE, cache.get(DATA_SIZE - CACHE_SIZE));
    Assert.assertEquals(DATA_SIZE - 2 * CACHE_SIZE, cache.get(DATA_SIZE - 2 * CACHE_SIZE));
    Assert.assertEquals(0, cache.get(0));
    Assert.assertEquals(4, cache.get(4));
    Assert.assertEquals(10, cache.get(10));
    Assert.assertEquals(1, cache.get(1));
    Assert.assertEquals(3, cache.get(3));
}

@Test
public void testPutAndGetOrderly() {
    for (int i = 0; i < DATA_SIZE; ++i) {
        cache.set(i, i);
    }
    for (int i = 0; i < DATA_SIZE; ++i) {
        Assert.assertEquals(i, cache.get(i));
    }
    for (int i = 0; i < DATA_SIZE; ++i) {
        cache.set(i, DATA_SIZE - i);
    }
    for (int i = 0; i < DATA_SIZE; ++i) {
        Assert.assertEquals(DATA_SIZE - i, cache.get(i));
    }
    for (int i = DATA_SIZE - 1; 0 <= i; --i) {
        cache.set(i, i);
    }
    for (int i = 0; i < DATA_SIZE; ++i) {
        cache.set(i, i);
    }
    for (int i = DATA_SIZE - 1; 0 <= i; --i) {
        cache.set(i, i);
        cache.set(i, i);
        cache.set(i, i);
    }
    for (int i = 0; i < DATA_SIZE; ++i) {
        cache.set(i, i);
    }
}

