@Test
public void testCacheHitRatioMonitor() {
    final double delta = 0.000001;
    ChunkCache.getInstance().clear();
    TimeSeriesMetadataCache.getInstance().clear();
    BloomFilterCache.getInstance().clear();
    CacheHitRatioMonitor cacheHitRatioMonitor = CacheHitRatioMonitor.getInstance();
    try {
        cacheHitRatioMonitor.start();
        assertEquals(ServiceType.CACHE_HIT_RATIO_DISPLAY_SERVICE, cacheHitRatioMonitor.getID());
        assertTrue(cacheHitRatioMonitor.getChunkHitRatio() >= 0.0d && cacheHitRatioMonitor.getChunkHitRatio() <= 1.0d);
        assertTrue(cacheHitRatioMonitor.getChunkEvictionCount() >= 0);
        assertEquals(ChunkCache.getInstance().getMaxMemory(), cacheHitRatioMonitor.getChunkCacheMaxMemory());
        assertTrue(cacheHitRatioMonitor.getChunkCacheAverageLoadPenalty() >= 0.0);
        assertTrue(cacheHitRatioMonitor.getChunkCacheAverageSize() >= 0);
        assertTrue(cacheHitRatioMonitor.getTimeSeriesMetadataHitRatio() >= 0.0d && cacheHitRatioMonitor.getTimeSeriesMetadataHitRatio() <= 1.0d);
        assertTrue(cacheHitRatioMonitor.getTimeSeriesMetadataCacheEvictionCount() >= 0);
        assertEquals(TimeSeriesMetadataCache.getInstance().getMaxMemory(), cacheHitRatioMonitor.getTimeSeriesMetadataCacheMaxMemory());
        assertTrue(cacheHitRatioMonitor.getTimeSeriesCacheAverageLoadPenalty() >= 0.0);
        assertTrue(cacheHitRatioMonitor.getTimeSeriesMetaDataCacheAverageSize() >= 0);
        assertTrue(cacheHitRatioMonitor.getBloomFilterHitRatio() >= 0.0d && cacheHitRatioMonitor.getBloomFilterHitRatio() <= 1.0d);
        assertTrue(cacheHitRatioMonitor.getBloomFilterCacheEvictionCount() >= 0);
        assertEquals(BloomFilterCache.getInstance().getMaxMemory(), cacheHitRatioMonitor.getBloomFilterCacheMaxMemory());
        assertTrue(cacheHitRatioMonitor.getBloomFilterCacheAverageLoadPenalty() >= 0.0);
        assertTrue(cacheHitRatioMonitor.getBloomFilterCacheAverageSize() >= 0);
        assertEquals(SystemInfo.getInstance().getTotalMemTableSize(), cacheHitRatioMonitor.getTotalMemTableSize());
        assertEquals(SystemInfo.getInstance().getFlushThershold(), cacheHitRatioMonitor.getFlushThershold(), delta);
        assertEquals(SystemInfo.getInstance().getRejectThershold(), cacheHitRatioMonitor.getRejectThershold(), delta);
        assertEquals(FlushManager.getInstance().getNumberOfWorkingTasks(), cacheHitRatioMonitor.flushingMemTableNum());
        assertEquals(MemTableManager.getInstance().getCurrentMemtableNumber(), cacheHitRatioMonitor.totalMemTableNum());
    } catch (StartupException e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        cacheHitRatioMonitor.stop();
    }
}

