@Test
public void testSelectWithTooManySourceFiles() throws IOException, MetadataException, WriteProcessException, InterruptedException {
    int oldMaxFileNumForCompaction = SystemInfo.getInstance().getTotalFileLimitForCrossTask();
    SystemInfo.getInstance().setTotalFileLimitForCrossTask(1);
    SystemInfo.getInstance().getCompactionFileNumCost().set(0);
    SystemInfo.getInstance().getCompactionMemoryCost().set(0);
    try {
        createFiles(19, 2, 3, 50, 0, 10000, 50, 50, false, true);
        createFiles(1, 2, 3, 3000, 0, 10000, 50, 50, false, false);
        RewriteCrossSpaceCompactionSelector selector = new RewriteCrossSpaceCompactionSelector("", "", 0, null);
        List<CrossCompactionTaskResource> selected = selector.selectCrossSpaceTask(seqResources, unseqResources);
        Assert.assertEquals(1, selected.size());
        Assert.assertEquals(19, selected.get(0).getSeqFiles().size());
        Assert.assertEquals(1, selected.get(0).getUnseqFiles().size());
        CrossSpaceCompactionTask crossSpaceCompactionTask = new CrossSpaceCompactionTask(0, tsFileManager, selected.get(0).getSeqFiles(), selected.get(0).getUnseqFiles(), IoTDBDescriptor.getInstance().getConfig().getCrossCompactionPerformer().createInstance(), 1000, tsFileManager.getNextCompactionTaskId());
        // set file status to COMPACTION_CANDIDATE
        Assert.assertTrue(crossSpaceCompactionTask.setSourceFilesToCompactionCandidate());
        FixedPriorityBlockingQueue<AbstractCompactionTask> mockQueue = Mockito.mock(FixedPriorityBlockingQueue.class);
        Mockito.when(mockQueue.take()).thenReturn(crossSpaceCompactionTask).thenThrow(new InterruptedException());
        CompactionWorker worker = new CompactionWorker(0, mockQueue);
        worker.run();
        Assert.assertEquals(0, SystemInfo.getInstance().getCompactionMemoryCost().get());
        Assert.assertEquals(0, SystemInfo.getInstance().getCompactionFileNumCost().get());
        for (TsFileResource resource : seqResources) {
            Assert.assertEquals(TsFileResourceStatus.NORMAL, resource.getStatus());
        }
        for (TsFileResource resource : unseqResources) {
            Assert.assertEquals(TsFileResourceStatus.NORMAL, resource.getStatus());
        }
    } finally {
        SystemInfo.getInstance().setTotalFileLimitForCrossTask(oldMaxFileNumForCompaction);
    }
}

@Test
public void testSeqFileWithDeviceIndexBeenDeletedDuringSelectionAndAfterCopyingList() throws IOException, MetadataException, WriteProcessException, InterruptedException {
    createFiles(5, 2, 3, 50, 0, 10000, 50, 50, false, true);
    createFiles(5, 2, 3, 50, 0, 10000, 50, 50, false, false);
    tsFileManager.addAll(seqResources, true);
    tsFileManager.addAll(unseqResources, false);
    AtomicBoolean fail = new AtomicBoolean(false);
    CountDownLatch cd1 = new CountDownLatch(1);
    CountDownLatch cd2 = new CountDownLatch(1);
    // select files in cross compaction
    Thread thread1 = new Thread(() -> {
        try {
            RewriteCrossSpaceCompactionSelector selector = new RewriteCrossSpaceCompactionSelector("", "", 0, null);
            // copy candidate source file list and add read lock
            CrossSpaceCompactionCandidate candidate = new CrossSpaceCompactionCandidate(seqResources, unseqResources, System.currentTimeMillis() - Long.MAX_VALUE);
            // the other thread holds write lock and delete file successfully after copying list
            cd1.countDown();
            cd2.await();
            CrossCompactionTaskResource crossCompactionTaskResource = selector.selectOneTaskResources(candidate);
            if (!crossCompactionTaskResource.isValid()) {
                throw new RuntimeException("compaction task resource is not valid");
            }
            if (crossCompactionTaskResource.getSeqFiles().size() != 1) {
                throw new RuntimeException("selected seq file should be 1");
            }
            if (crossCompactionTaskResource.getUnseqFiles().size() != 1) {
                throw new RuntimeException("selected unseq file num should be 1");
            }
            CrossSpaceCompactionTask crossSpaceCompactionTask = new CrossSpaceCompactionTask(0, tsFileManager, crossCompactionTaskResource.getSeqFiles(), crossCompactionTaskResource.getUnseqFiles(), IoTDBDescriptor.getInstance().getConfig().getCrossCompactionPerformer().createInstance(), crossCompactionTaskResource.getTotalMemoryCost(), tsFileManager.getNextCompactionTaskId());
            // set file status to COMPACTION_CANDIDATE
            if (!crossSpaceCompactionTask.setSourceFilesToCompactionCandidate()) {
                throw new RuntimeException("set status should be true");
            }
            for (int i = 0; i < seqResources.size(); i++) {
                TsFileResource resource = seqResources.get(i);
                if (i < 1) {
                    if (resource.getStatus() != TsFileResourceStatus.COMPACTION_CANDIDATE) {
                        throw new RuntimeException("status should be COMPACTION_CANDIDATE");
                    }
                } else if (i == 1) {
                    if (resource.getStatus() != TsFileResourceStatus.DELETED) {
                        throw new RuntimeException("status should be DELETED");
                    }
                } else if (resource.getStatus() != TsFileResourceStatus.NORMAL) {
                    throw new RuntimeException("status should be NORMAL");
                }
            }
            for (int i = 0; i < unseqResources.size(); i++) {
                TsFileResource resource = unseqResources.get(i);
                if (i < 1) {
                    if (resource.getStatus() != TsFileResourceStatus.COMPACTION_CANDIDATE) {
                        throw new RuntimeException("status should be COMPACTION_CANDIDATE");
                    }
                } else if (resource.getStatus() != TsFileResourceStatus.NORMAL) {
                    throw new RuntimeException("status should be NORMAL");
                }
            }
        } catch (Exception e) {
            fail.set(true);
            e.printStackTrace();
        }
    });
    // delete seq files
    Thread thread2 = new Thread(() -> {
        try {
            cd1.await();
            TsFileResource resource = seqResources.get(1);
            // try to delete file
            resource.writeLock();
            resource.remove();
            resource.writeUnlock();
            cd2.countDown();
        } catch (Exception e) {
            fail.set(true);
            e.printStackTrace();
        }
    });
    thread1.start();
    thread2.start();
    thread1.join(10000);
    thread2.join(10000);
    if (fail.get()) {
        Assert.fail();
    }
}

