            File file = new File(TestConstant.BASE_OUTPUT_PATH.concat(System.currentTimeMillis() + IoTDBConstant.FILE_NAME_SEPARATOR + i + IoTDBConstant.FILE_NAME_SEPARATOR + 10 + IoTDBConstant.FILE_NAME_SEPARATOR + 0 + ".tsfile"));
