            IDataBlockReader tsFilesReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), tsFileManager.getTsFileList(true), new ArrayList<>(), true);
