            check(targetResources.get(i), deviceIdList);
        }
        deviceIdList.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2");
        deviceIdList.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3");
        for (int i = 1; i < 2; i++) {
            Assert.assertTrue(targetResources.get(i).isDeviceIdExist(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0"));
            Assert.assertTrue(targetResources.get(i).isDeviceIdExist(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1"));
            Assert.assertTrue(targetResources.get(i).isDeviceIdExist(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2"));
            Assert.assertTrue(targetResources.get(i).isDeviceIdExist(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3"));
            check(targetResources.get(i), deviceIdList);
        }
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                PartialPath path = new MeasurementPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, "s" + j, new MeasurementSchema("s" + j, TSDataType.INT64));
                IDataBlockReader tsBlockReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), targetResources, new ArrayList<>(), true);
                int count = 0;
                while (tsBlockReader.hasNextBatch()) {
                    TsBlock block = tsBlockReader.nextBatch();
                    IBatchDataIterator iterator = block.getTsBlockSingleColumnIterator();
                    while (iterator.hasNext()) {
                        if (iterator.currentTime() < 20) {
                            assertEquals(iterator.currentTime(), iterator.currentValue());
                        } else {
                            assertEquals(iterator.currentTime() + 10000, iterator.currentValue());
                        }
                        count++;
                        iterator.next();
                    }
                }
                tsBlockReader.close();
                if (i < 2 && j < 3) {
                    assertEquals(920, count);
                } else {
                    assertEquals(900, count);
                }
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail();
    }
}

