        while (modificationFile.getSize() < 1024 * 1024) {
            for (int i = 0; i < 5; i++) {
                modificationFile.write(new Deletion(new PartialPath(new String[] { "root", "sg", "d1" }), 1000, Long.MIN_VALUE, time += 5000));
                modificationFile.write(new Deletion(new PartialPath(new String[] { "root", "sg", "*" }), 1000, Long.MIN_VALUE, time += 5000));
            }
        }
        modificationFile.compact();
        List<Modification> modificationList = new ArrayList<>(modificationFile.getModifications());
        assertEquals(2, modificationList.size());
    } catch (IOException e) {
        fail(e.getMessage());
    } finally {
        new File(tempFileName).delete();
    }
}

