@Test
public void testTriggerExecutor() {
    try {
        TriggerInformation triggerInformation = new TriggerInformation(new PartialPath("root.sg.**"), "test1", "org.apache.iotdb.db.trigger.service.TestTrigger", false, "test1.jar", null, TriggerEvent.AFTER_INSERT, TTriggerState.ACTIVE, false, null, FailureStrategy.OPTIMISTIC, "testMD5test");
        Trigger trigger = new TestTrigger();
        TriggerExecutor executor = new TriggerExecutor(triggerInformation, trigger, false);
        TriggerManagementService.getInstance().fakeRegister(triggerInformation, executor);
        InsertRowNode insertRowNode = getInsertRowNodeWithMeasurementSchemas();
        TriggerFireVisitor fireVisitor = new TriggerFireVisitor();
        TriggerFireResult result = fireVisitor.process(insertRowNode, TriggerEvent.AFTER_INSERT);
        Assert.assertEquals(TriggerFireResult.SUCCESS, result);
        executor.onDrop();
        TestTrigger test = (TestTrigger) trigger;
        Assert.assertTrue((test.onCreated));
        Assert.assertTrue((test.onValidated));
        Assert.assertTrue((test.onFired));
        Assert.assertTrue((test.onDropped));
        Assert.assertEquals(FailureStrategy.OPTIMISTIC, executor.getFailureStrategy());
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail();
    }
}

@Test
public void testRegisterAndActiveAndInactiveAndDrop() {
    try {
        TriggerInformation triggerInformation = new TriggerInformation(new PartialPath("root.test.**"), "test1", "org.apache.iotdb.db.trigger.service.TestTrigger", false, "test1.jar", null, TriggerEvent.AFTER_INSERT, TTriggerState.INACTIVE, false, null, FailureStrategy.OPTIMISTIC, "testMD5test");
        List<TriggerInformation> triggerInformationList = SERVICE.getAllTriggerInformationInTriggerTable();
        Assert.assertEquals(0, triggerInformationList.size());
        try {
            SERVICE.doRegister(triggerInformation, false);
        } catch (TriggerManagementException e) {
            if (!e.getMessage().contains("reflect")) {
                Assert.fail();
            }
        }
        triggerInformationList = SERVICE.getAllTriggerInformationInTriggerTable();
        Assert.assertEquals(1, triggerInformationList.size());
        Assert.assertEquals(triggerInformation, triggerInformationList.get(0));
        Assert.assertEquals(TTriggerState.INACTIVE, triggerInformationList.get(0).getTriggerState());
        SERVICE.activeTrigger("test1");
        Assert.assertEquals(TTriggerState.ACTIVE, SERVICE.getAllTriggerInformationInTriggerTable().get(0).getTriggerState());
        SERVICE.inactiveTrigger("test1");
        Assert.assertEquals(TTriggerState.INACTIVE, SERVICE.getAllTriggerInformationInTriggerTable().get(0).getTriggerState());
        SERVICE.dropTrigger("test1", false);
        Assert.assertEquals(0, SERVICE.getAllTriggerInformationInTriggerTable().size());
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail();
    }
}

@Test
public void modifyListTest() {
    CopyOnReadLinkedList<String> slist = new CopyOnReadLinkedList<>();
    String str1 = "aaa";
    String str2 = "bbb";
    slist.add(str1);
    slist.add(str2);
    Iterator<String> iterator = slist.iterator();
    Assert.assertEquals(str1, iterator.next());
    Assert.assertEquals(str2, iterator.next());
    slist.reset();
    if (slist.contains(str1)) {
        slist.remove(str1);
    }
    Assert.assertEquals(1, slist.size());
    str2 = "ddd";
    // str2 in slist is not modified
    iterator = slist.iterator();
    Assert.assertNotEquals(str2, iterator.next());
}

@Test
public void cloneModifiedListTest() {
    CopyOnReadLinkedList<String> slist = new CopyOnReadLinkedList<>();
    String str1 = "aaa";
    String str2 = "bbb";
    slist.add(str1);
    slist.add(str2);
    str2 = "ddd";
    // str2 in slist is not modified
    List<String> clist = slist.cloneList();
    Assert.assertEquals("aaa", clist.get(0));
    Assert.assertEquals("bbb", clist.get(1));
    Assert.assertFalse(clist.isEmpty());
}

