@Test
public void testConcurrentTake() throws InterruptedException {
    final FixedPriorityBlockingQueue<Integer> testQueue = new FixedPriorityBlockingQueue<>(100, Integer::compare);
    Random random = new Random(10);
    List<Integer> resultList = new ArrayList<>();
    ReentrantLock lock = new ReentrantLock();
    List<Integer> expectedList = new ArrayList<>();
    for (int i = 0; i < 90; ++i) {
        int curr = random.nextInt();
        testQueue.put(curr);
        expectedList.add(curr);
    }
    Collections.sort(expectedList);
    Thread t1 = new Thread(() -> {
        try {
            while (resultList.size() < 90) {
                lock.lock();
                try {
                    if (resultList.size() >= 90) {
                        return;
                    }
                    int curr = testQueue.take();
                    resultList.add(curr);
                } finally {
                    lock.unlock();
                }
            }
        } catch (InterruptedException e) {
        }
    });
    Thread t2 = new Thread(() -> {
        try {
            while (resultList.size() < 90) {
                lock.lock();
                try {
                    if (resultList.size() >= 90) {
                        return;
                    }
                    int curr = testQueue.take();
                    resultList.add(curr);
                } finally {
                    lock.unlock();
                }
            }
        } catch (InterruptedException e) {
        }
    });
    Thread t3 = new Thread(() -> {
        try {
            while (resultList.size() < 90) {
                lock.lock();
                try {
                    if (resultList.size() >= 90) {
                        return;
                    }
                    int curr = testQueue.take();
                    resultList.add(curr);
                } finally {
                    lock.unlock();
                }
            }
