@Test
public void testIntersectWithFullPathPrefixTree1() throws Exception {
    List<PartialPath> partialPathList = Arrays.asList(new PartialPath("root.sg1.d1.t1.s1"), new PartialPath("root.sg1.*.t1.s1"), new PartialPath("root.sg1.d2.**"));
    PathPatternTree patternTree = new PathPatternTree();
    for (PartialPath path : partialPathList) {
        patternTree.appendPathPattern(path);
    }
    patternTree.constructTree();
    List<PartialPath> fullPathPrefixList = Arrays.asList(new PartialPath("root.sg1.d1.**"), new PartialPath("root.sg1.d2.**"), new PartialPath("root.sg1.d3.t1.s1"));
    PathPatternTree fullPathPrefixTree = new PathPatternTree();
    for (PartialPath path : fullPathPrefixList) {
        fullPathPrefixTree.appendPathPattern(path);
    }
    fullPathPrefixTree.constructTree();
    PathPatternTree res = PathPatternTreeUtils.intersectWithFullPathPrefixTree(patternTree, fullPathPrefixTree);
    Set<PartialPath> expected = new HashSet<PartialPath>() {

        {
            add(new PartialPath("root.sg1.d1.t1.s1"));
            add(new PartialPath("root.sg1.d2.**"));
            add(new PartialPath("root.sg1.d3.t1.s1"));
        }
    };
    for (PartialPath path : res.getAllPathPatterns()) {
        Assert.assertTrue(expected.remove(path));
    }
    Assert.assertTrue(expected.isEmpty());
}

