    Assert.assertEquals(new In<>(new HashSet<>(Arrays.asList("a", "b")), FilterType.TIME_FILTER, true), new In<>(new HashSet<>(Arrays.asList("a", "b")), FilterType.TIME_FILTER, false).reverse());
    Assert.assertEquals(new In<>(new HashSet<>(Arrays.asList("a", "b")), FilterType.TIME_FILTER, false), new In<>(new HashSet<>(Arrays.asList("a", "b")), FilterType.TIME_FILTER, true).reverse());
