        }
        if (i < 2) {
            Assert.assertEquals(60, cnt);
        } else {
            Assert.assertEquals(30, cnt);
        }
    }
}

@Test
public void writeTsFileByFlushingPageDirectly() throws IOException, WriteProcessException {
    TSFileDescriptor.getInstance().getConfig().setMaxNumberOfPointsInPage(30);
    // create a tsfile with four pages in one timeseries
    try (TsFileWriter tsFileWriter = new TsFileWriter(f)) {
        registerTimeseries(tsFileWriter);
        List<MeasurementSchema> writeMeasurementSchemas = new ArrayList<>();
        writeMeasurementSchemas.add(measurementSchemas.get(0));
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementSchemas, 30, 0, 0, false);
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementSchemas, 30, 30, 30, false);
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementSchemas, 30, 60, 60, false);
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementSchemas, 30, 90, 90, false);
    }
    ChunkWriterImpl chunkWriter = new ChunkWriterImpl(measurementSchemas.get(0));
    // rewrite a new tsfile by flushing page directly
    File file = FSFactoryProducer.getFSFactory().getFile("test.tsfile");
    try (TsFileSequenceReader reader = new TsFileSequenceReader(f.getAbsolutePath());
        TsFileIOWriter tsFileIOWriter = new TsFileIOWriter(file)) {
        tsFileIOWriter.startChunkGroup(deviceId);
        for (List<ChunkMetadata> chunkMetadatas : reader.readChunkMetadataInDevice(deviceId).values()) {
            for (ChunkMetadata chunkMetadata : chunkMetadatas) {
                Chunk chunk = reader.readMemChunk(chunkMetadata);
                ByteBuffer chunkDataBuffer = chunk.getData();
                ChunkHeader chunkHeader = chunk.getHeader();
                int pageNum = 0;
                while (chunkDataBuffer.remaining() > 0) {
                    // deserialize a PageHeader from chunkDataBuffer
                    PageHeader pageHeader;
                    if (((byte) (chunkHeader.getChunkType() & 0x3F)) == MetaMarker.ONLY_ONE_PAGE_CHUNK_HEADER) {
                        pageHeader = PageHeader.deserializeFrom(chunkDataBuffer, chunk.getChunkStatistic());
                    } else {
                        pageHeader = PageHeader.deserializeFrom(chunkDataBuffer, chunkHeader.getDataType());
                    }
                    // read compressed page data
                    int compressedPageBodyLength = pageHeader.getCompressedSize();
                    byte[] compressedPageBody = new byte[compressedPageBodyLength];
                    chunkDataBuffer.get(compressedPageBody);
                    chunkWriter.writePageHeaderAndDataIntoBuff(ByteBuffer.wrap(compressedPageBody), pageHeader);
                    if (++pageNum % 2 == 0) {
                        chunkWriter.writeToFileWriter(tsFileIOWriter);
                    }
                }
            }
        }
        tsFileIOWriter.endChunkGroup();
        tsFileIOWriter.endFile();
        // read file
        TsFileReader tsFileReader = new TsFileReader(new TsFileSequenceReader(file.getAbsolutePath()));
        QueryExpression queryExpression = QueryExpression.create(Collections.singletonList(new Path(deviceId, measurementSchemas.get(0).getMeasurementId(), true)), null);
        QueryDataSet queryDataSet = tsFileReader.query(queryExpression);
        int cnt = 0;
        while (queryDataSet.hasNext()) {
            cnt++;
            // Assert.assertEquals(queryDataSet);
            queryDataSet.next();
        }
        Assert.assertEquals(120, cnt);
    } catch (Throwable throwable) {
        if (file.exists()) {
            file.delete();
        }
        throw throwable;
    }
}

